-- Compiled relations: per-store, opt-in generated SQL functions.
--
-- A store opted in with enable_compiled_relations gets, for every
-- (type, relation) of its latest model, three plain LANGUAGE sql
-- functions in a schema the application owns:
--
--   <type>__<relation>__objects   subject -> objects (list_objects)
--   <type>__<relation>__subjects  object -> subjects (final list)
--   <type>__<relation>__check     object + subject -> boolean
--
-- They are regenerated by every write_authorization_model of that
-- store, in the same transaction, and recorded in
-- fga.compiled_relation together with the strategy each relation
-- compiled to. The registry, never a name pattern, says which
-- functions the engine owns: cleanup drops exactly what is
-- registered.
--
-- Generated functions carry no SET clause (it would block
-- inlining into the caller's query), so their bodies
-- schema-qualify every table, function, type and operator
-- instead. The hand-written functions in this file keep the
-- usual SET search_path.
--
-- Strategies: each relation compiles to its own emitter.
--   flattened    a UNION of fixed joins over fga.tuple (direct
--                grants, wildcards, usersets, computed usersets,
--                tuple-to-userset) for relations without cycles,
--                set operations or conditions;
--   conditioned  the flattened shape, with the relation's own
--                conditioned grants filtered through the condition
--                evaluator and the request context;
--   setop        intersection and exclusion as INTERSECT / EXCEPT
--                (AND / AND NOT for __check) over the same arms;
--   recursive    a WITH RECURSIVE walk over the tuple graph for
--                relations on (or reaching) a cycle of the relation
--                graph, or deep enough to meet check's depth limit;
--   delegated    same signature, body calls the generic resolver;
--                used for anything no other emitter answers exactly
--                (the reason column says why).
--
-- The flattened, conditioned and set-operation strategies read a
-- call's contextual tuples themselves, as a source beside
-- fga.tuple. A recursive body hands a call that carries contextual
-- tuples to the generic resolver: its walk joins fga.tuple on the
-- previous step's node, and a second source there would lose the
-- index path every step relies on.

CREATE TABLE IF NOT EXISTS fga.compiled_store (
  store uuid NOT NULL,
  target_schema text NOT NULL,
  subject_sources jsonb,
  PRIMARY KEY (store)
);

-- One store per schema: two stores' functions would share names.
CREATE UNIQUE INDEX IF NOT EXISTS compiled_store_schema_idx
  ON fga.compiled_store (target_schema);

CREATE TABLE IF NOT EXISTS fga.compiled_relation (
  store uuid NOT NULL,
  model_id uuid NOT NULL,
  type_name text NOT NULL,
  relation_name text NOT NULL,
  objects_fn regprocedure NOT NULL,
  subjects_fn regprocedure NOT NULL,
  check_fn regprocedure NOT NULL,
  strategy text NOT NULL,
  reason text,
  PRIMARY KEY (store, model_id, type_name, relation_name)
);

-- The dynamic statement each flattened or conditioned function runs
-- for a call that carries contextual tuples (_compiled_ctx_set),
-- kept out of the function bodies: a body is parsed whenever the
-- caller's statement is planned, and the statements would triple
-- it for the call that carries none.
CREATE TABLE IF NOT EXISTS fga.compiled_contextual (
  store uuid NOT NULL,
  model_id uuid NOT NULL,
  type_name text NOT NULL,
  relation_name text NOT NULL,
  kind text NOT NULL,
  stmt text NOT NULL,
  PRIMARY KEY (store, model_id, type_name, relation_name, kind)
);

-- The generated function name for one (type, relation, kind)
-- (decision 11). Readable when both source names are plain
-- lower-case words joined by single underscores and the result
-- fits PostgreSQL's 63-byte identifiers; otherwise a sanitised
-- prefix, then 8 hex of a hash of the exact names, then the kind.
-- The plain form excludes "__" and leading or trailing "_" in the
-- source names, so two different pairs can never join into the
-- same readable name; the generator still refuses any collision.
CREATE OR REPLACE FUNCTION fga._compiled_name(
  type_name text, relation_name text, kind text
)
RETURNS text
LANGUAGE sql
IMMUTABLE PARALLEL SAFE
SET search_path = fga, pg_temp
AS $$
  SELECT CASE
    WHEN type_name ~ '^[a-z][a-z0-9]*(_[a-z0-9]+)*$'
     AND relation_name ~ '^[a-z][a-z0-9]*(_[a-z0-9]+)*$'
     AND octet_length(plain) <= 63
    THEN plain
    ELSE left(
      regexp_replace(lower(type_name || '__' || relation_name),
        '[^abcdefghijklmnopqrstuvwxyz0123456789_]', '_', 'g'),
      63 - octet_length(suffix)) || suffix
  END
  FROM (SELECT
    type_name || '__' || relation_name || '__' || kind AS plain,
    '_' || left(md5(type_name || '#' || relation_name || '#' || kind),
                8) || '_' || kind AS suffix) AS n;
$$;

-- Subject validation shared by every generated function: the nil
-- uuid is refused as an id exactly like the public API, and
-- "any subject" (the type:* question) is its own flag. Returns the
-- id to match — the nil sentinel for "any subject" — so the
-- sentinel never crosses the function surface.
CREATE OR REPLACE FUNCTION fga._compiled_sid(
  subject_id uuid, any_subject boolean, subject_relation text
)
RETURNS uuid
LANGUAGE plpgsql
IMMUTABLE PARALLEL SAFE
SET search_path = fga, pg_temp
AS $$
BEGIN
  IF any_subject IS NULL THEN
    RAISE EXCEPTION 'invalid subject: p_any_subject must not be null'
      USING ERRCODE = 'YF100';
  END IF;
  IF any_subject THEN
    IF subject_id IS NOT NULL THEN
      RAISE EXCEPTION 'invalid subject: p_any_subject asks about '
        'any subject and takes no subject id' USING ERRCODE = 'YF100';
    END IF;
    IF coalesce(subject_relation, '') <> '' THEN
      RAISE EXCEPTION 'invalid subject: a wildcard subject cannot '
        'carry a relation' USING ERRCODE = 'YF100';
    END IF;
    RETURN '00000000-0000-0000-0000-000000000000';
  END IF;
  IF subject_id IS NULL
     OR subject_id = '00000000-0000-0000-0000-000000000000' THEN
    RAISE EXCEPTION 'invalid user id ''%'': not a canonical uuid '
      '(fga4postgres id domain)', coalesce(subject_id::text, '')
      USING ERRCODE = 'YF100';
  END IF;
  RETURN subject_id;
END;
$$;

CREATE OR REPLACE FUNCTION fga._compiled_oid(object_id uuid)
RETURNS uuid
LANGUAGE plpgsql
IMMUTABLE PARALLEL SAFE
SET search_path = fga, pg_temp
AS $$
BEGIN
  IF object_id IS NULL
     OR object_id = '00000000-0000-0000-0000-000000000000' THEN
    RAISE EXCEPTION 'invalid object id ''%'': not a canonical '
      'uuid (fga4postgres id domain)', coalesce(object_id::text, '')
      USING ERRCODE = 'YF100';
  END IF;
  RETURN object_id;
END;
$$;

-- The "type:id[#relation]" / "type:*" user string of a subject.
CREATE OR REPLACE FUNCTION fga._compiled_user(
  subject_type text, subject_id uuid, subject_relation text,
  any_subject boolean
)
RETURNS text
LANGUAGE sql
IMMUTABLE PARALLEL SAFE
SET search_path = fga, pg_temp
AS $$
  SELECT subject_type || ':' || CASE
    WHEN fga._compiled_sid(subject_id, any_subject, subject_relation)
         = '00000000-0000-0000-0000-000000000000'
    THEN '*'
    ELSE subject_id::text || CASE
      WHEN coalesce(subject_relation, '') <> ''
      THEN '#' || subject_relation ELSE '' END
  END;
$$;

-- The generic resolver behind delegated functions. The model id
-- is the one the function was compiled from, so a delegated
-- answer never comes from another model.
--
-- These hand-offs set fga._dispatching (see fga._check_compiled)
-- for their own duration, so the public entry point they call
-- answers generically: on an opted-in store it would otherwise
-- dispatch straight back to the generated function that handed
-- the question off (a recursive relation given contextual tuples,
-- called directly), which would hand it off again.
CREATE OR REPLACE FUNCTION fga._compiled_check(
  store_id uuid, model_id uuid, object_type text, relation text,
  object_id uuid, subject_type text, subject_id uuid,
  subject_relation text, any_subject boolean,
  context jsonb, contextual_tuples jsonb
)
RETURNS boolean
LANGUAGE sql
STABLE PARALLEL SAFE
SET search_path = fga, pg_temp
SET fga._dispatching = 'on'
AS $$
  SELECT (fga.check(store_id, jsonb_build_object(
    'authorization_model_id', model_id::text,
    'tuple_key', jsonb_build_object(
      'object', object_type || ':' || fga._compiled_oid(object_id),
      'relation', relation,
      'user', fga._compiled_user(subject_type, subject_id,
                                 subject_relation, any_subject)),
    'context', context,
    'contextual_tuples', jsonb_build_object(
      'tuple_keys', coalesce(contextual_tuples, '[]'::jsonb))
  )) ->> 'allowed')::boolean;
$$;

-- Delegated objects go through streamed_list_objects, which is
-- uncapped like every generated __objects.
CREATE OR REPLACE FUNCTION fga._compiled_objects(
  store_id uuid, model_id uuid, object_type text, relation text,
  subject_type text, subject_id uuid, subject_relation text,
  any_subject boolean, context jsonb, contextual_tuples jsonb
)
RETURNS SETOF uuid
LANGUAGE sql
STABLE PARALLEL SAFE
SET search_path = fga, pg_temp
SET fga._dispatching = 'on'
AS $$
  SELECT split_part(o ->> 'object', ':', 2)::uuid
  FROM fga.streamed_list_objects(store_id,
    jsonb_build_object(
      'authorization_model_id', model_id::text,
      'type', object_type,
      'relation', relation,
      'user', fga._compiled_user(subject_type, subject_id,
                                 subject_relation, any_subject),
      'context', context,
      'contextual_tuples', jsonb_build_object(
        'tuple_keys', coalesce(contextual_tuples, '[]'::jsonb))
    )) AS o;
$$;

-- The rows of a registered subject source ("schema.table(column)").
CREATE OR REPLACE FUNCTION fga._compiled_source_ids(
  store_id uuid, subject_type text
)
RETURNS SETOF uuid
LANGUAGE plpgsql
STABLE PARALLEL SAFE
SET search_path = fga, pg_temp
AS $$
DECLARE
  src text;
  m text[];
BEGIN
  SELECT cs.subject_sources ->> subject_type INTO src
  FROM fga.compiled_store cs WHERE cs.store = store_id;
  IF src IS NULL THEN
    RAISE EXCEPTION 'no subject source registered for type ''%'': '
      'a wildcard grant cannot be expanded into a list of subjects',
      subject_type USING ERRCODE = 'YF100';
  END IF;
  m := fga._compiled_parse_source(src);
  RETURN QUERY EXECUTE format('SELECT %I FROM %I.%I',
    m[3], m[1], m[2]);
END;
$$;

-- Delegated subjects: the generic list_users search, uncapped,
-- turned into the final list __subjects promises (decision 8).
-- list_users answers in upstream's shape, so its users are mapped:
-- an object user is its id; a userset user (the filter names a
-- relation) is the userset's id; and a typed wildcard expands over
-- the registered subject source, keeping only the subjects check
-- allows — upstream's shape hides a wildcard's exclusions (user:*
-- but not bob is just user:*), and check is what applies them.
CREATE OR REPLACE FUNCTION fga._compiled_subjects(
  store_id uuid, model_id uuid, object_type text, relation text,
  object_id uuid, subject_type text, subject_relation text,
  context jsonb, contextual_tuples jsonb
)
RETURNS SETOF uuid
LANGUAGE plpgsql
STABLE PARALLEL SAFE
SET search_path = fga, pg_temp
SET fga._dispatching = 'on'
AS $$
DECLARE
  users jsonb;
  filter jsonb := jsonb_build_object('type', subject_type);
BEGIN
  IF coalesce(subject_relation, '') <> '' THEN
    filter := filter || jsonb_build_object(
      'relation', subject_relation);
  END IF;
  users := fga._list_users(store_id, jsonb_build_object(
    'authorization_model_id', model_id::text,
    'object', jsonb_build_object(
      'type', object_type, 'id', fga._compiled_oid(object_id)),
    'relation', relation,
    'user_filters', jsonb_build_array(filter),
    'context', context,
    'contextual_tuples', coalesce(contextual_tuples, '[]'::jsonb)
  ), 0) -> 'users';

  IF NOT EXISTS (
    SELECT FROM jsonb_array_elements(users) AS u
    WHERE u ? 'wildcard'
  ) THEN
    RETURN QUERY
    SELECT coalesce(u -> 'object' ->> 'id',
                    u -> 'userset' ->> 'id')::uuid
    FROM jsonb_array_elements(users) AS u
    WHERE u ? 'object' OR u ? 'userset';
    RETURN;
  END IF;

  RETURN QUERY
  SELECT (u -> 'object' ->> 'id')::uuid
  FROM jsonb_array_elements(users) AS u
  WHERE u ? 'object'
  UNION
  SELECT s.id FROM fga._compiled_source_ids(
    store_id, subject_type) AS s(id)
  WHERE fga._compiled_check(store_id, model_id, object_type,
    relation, object_id, subject_type, s.id, '', false,
    context, contextual_tuples);
END;
$$;

-- "schema.table(column)" -> {schema, table, column}; NULL when the
-- text does not have that shape.
CREATE OR REPLACE FUNCTION fga._compiled_parse_source(src text)
RETURNS text[]
LANGUAGE sql
IMMUTABLE PARALLEL SAFE
SET search_path = fga, pg_temp
AS $$
  SELECT regexp_match(src,
    '^([A-Za-z_][A-Za-z0-9_$]*)\.([A-Za-z_][A-Za-z0-9_$]*)'
    '\(([A-Za-z_][A-Za-z0-9_$]*)\)$');
$$;

-- The generated signatures, one per kind. Every type is qualified
-- so the signature text doubles as a regprocedure literal.
CREATE OR REPLACE FUNCTION fga._compiled_params(kind text)
RETURNS text
LANGUAGE sql
IMMUTABLE PARALLEL SAFE
SET search_path = fga, pg_temp
AS $$
  SELECT CASE kind
    WHEN 'objects' THEN
      'p_subject_type pg_catalog.text, p_subject_id pg_catalog.uuid, '
      'p_subject_relation pg_catalog.text DEFAULT '''', '
      'p_any_subject pg_catalog.bool DEFAULT false, '
      'p_context pg_catalog.jsonb DEFAULT ''{}'', '
      'p_contextual_tuples pg_catalog.jsonb DEFAULT ''[]'''
    WHEN 'subjects' THEN
      'p_object pg_catalog.uuid, p_subject_type pg_catalog.text, '
      'p_subject_relation pg_catalog.text DEFAULT '''', '
      'p_context pg_catalog.jsonb DEFAULT ''{}'', '
      'p_contextual_tuples pg_catalog.jsonb DEFAULT ''[]'''
    WHEN 'check' THEN
      'p_object pg_catalog.uuid, p_subject_type pg_catalog.text, '
      'p_subject_id pg_catalog.uuid, '
      'p_subject_relation pg_catalog.text DEFAULT '''', '
      'p_any_subject pg_catalog.bool DEFAULT false, '
      'p_context pg_catalog.jsonb DEFAULT ''{}'', '
      'p_contextual_tuples pg_catalog.jsonb DEFAULT ''[]'''
  END;
$$;

CREATE OR REPLACE FUNCTION fga._compiled_arg_types(kind text)
RETURNS text
LANGUAGE sql
IMMUTABLE PARALLEL SAFE
SET search_path = fga, pg_temp
AS $$
  SELECT CASE kind
    WHEN 'objects' THEN
      'pg_catalog.text, pg_catalog.uuid, pg_catalog.text, '
      'pg_catalog.bool, pg_catalog.jsonb, pg_catalog.jsonb'
    WHEN 'subjects' THEN
      'pg_catalog.uuid, pg_catalog.text, pg_catalog.text, '
      'pg_catalog.jsonb, pg_catalog.jsonb'
    WHEN 'check' THEN
      'pg_catalog.uuid, pg_catalog.text, pg_catalog.uuid, '
      'pg_catalog.text, pg_catalog.bool, pg_catalog.jsonb, '
      'pg_catalog.jsonb'
  END;
$$;

-- The function's definition around a body. LANGUAGE sql, STABLE,
-- SECURITY INVOKER and no SET clause: the shape PostgreSQL inlines.
CREATE OR REPLACE FUNCTION fga._compiled_ddl(
  target text, name text, kind text, body text
)
RETURNS text
LANGUAGE sql
IMMUTABLE PARALLEL SAFE
SET search_path = fga, pg_temp
AS $$
  SELECT format(
    'CREATE OR REPLACE FUNCTION %I.%I(%s) RETURNS %s '
    'LANGUAGE sql STABLE PARALLEL SAFE SECURITY INVOKER AS %L',
    target, name, fga._compiled_params(kind),
    CASE kind WHEN 'check' THEN 'pg_catalog.bool'
              ELSE 'SETOF pg_catalog.uuid' END,
    body);
$$;

CREATE OR REPLACE FUNCTION fga._compiled_comment(
  store_id uuid, model_id uuid, type_name text, relation_name text,
  kind text, strategy text, reason text
)
RETURNS text
LANGUAGE sql
IMMUTABLE PARALLEL SAFE
SET search_path = fga, pg_temp
AS $$
  SELECT format(
    'Compiled relation function — type: %s; relation: %s; '
    'kind: %s; store: %s; model id: %s; strategy: %s%s. This '
    'function is generated by fga4postgres from the authorization '
    'model; do not edit: every model write replaces it.',
    type_name, relation_name, kind, store_id, model_id, strategy,
    CASE WHEN reason IS NOT NULL THEN ' (' || reason || ')'
         ELSE '' END);
$$;

-- The test a generated body makes for "this call carries no
-- contextual tuples", as text. Inline rather than a function call:
-- a call would be one more non-inlinable call (its SET clause) in
-- every arm, where the expression costs nothing and folds at plan
-- time when the call passes the '[]' default, so the planner drops
-- every contextual-tuple branch.
CREATE OR REPLACE FUNCTION fga._compiled_no_ctuples_sql()
RETURNS text
LANGUAGE sql
IMMUTABLE PARALLEL SAFE
SET search_path = fga, pg_temp
AS $$
  SELECT '(p_contextual_tuples IS NULL OR p_contextual_tuples '
    'OPERATOR(pg_catalog.=) ''[]''::pg_catalog.jsonb)';
$$;

-- The contextual tuples of a generated call, validated exactly as
-- the public API validates them (write-grade, against the model
-- the function was compiled from). cond_errcode is the API's code
-- for a condition-binding refusal: check refuses it as an invalid
-- tuple, the list APIs as a validation error.
--
-- COST and ROWS say what a call really is — a handful of tuples, or
-- none. A generated body run as its own statement (anything not
-- inlined, a nested __check above all) is planned through the plan
-- cache, which keeps a generic plan only when it costs about what
-- the custom ones do; priced at the defaults, the contextual
-- branches of the generic plan made it lose, and every call was
-- planned again (a point check went from 0.12 ms to 1.15 ms).
CREATE OR REPLACE FUNCTION fga._compiled_ctx(
  store_id uuid, model_id uuid, tuples jsonb, cond_errcode text
)
RETURNS SETOF fga._tuple_key
LANGUAGE plpgsql
STABLE PARALLEL SAFE
COST 1 ROWS 10
SET search_path = fga, pg_temp
AS $$
DECLARE
  tkj jsonb;
  v record;
BEGIN
  FOR tkj IN
    SELECT * FROM jsonb_array_elements(coalesce(tuples, '[]'))
  LOOP
    SELECT * INTO v FROM fga._validate_tuple(
      store_id, model_id,
      tkj ->> 'object', tkj ->> 'relation', tkj ->> 'user',
      tkj -> 'condition' ->> 'name',
      'YF127', cond_errcode);
    RETURN NEXT (v.object_type, v.object_id, v.relation,
      v.subject_type, v.subject_id, v.subject_relation,
      tkj -> 'condition' ->> 'name',
      tkj -> 'condition' -> 'context')::fga._tuple_key;
  END LOOP;
END;
$$;

-- True, or the validation error of the first invalid contextual
-- tuple: the guard every generated body runs before answering, so
-- an invalid tuple is refused even when no read would reach it.
CREATE OR REPLACE FUNCTION fga._compiled_ctx_valid(
  store_id uuid, model_id uuid, tuples jsonb, cond_errcode text
)
RETURNS boolean
LANGUAGE sql
STABLE PARALLEL SAFE
SET search_path = fga, pg_temp
AS $$
  SELECT count(*) >= 0
  FROM fga._compiled_ctx(store_id, model_id, tuples, cond_errcode);
$$;

-- Where a generated body reads the rows of one (type, relation):
-- two sources, each a {FROM item, base condition} pair for alias g
-- — the stored rows, and the call's contextual tuples (that branch
-- folds away when the call passes none). An arm is emitted once per
-- source rather than over one UNION ALL of both, because PostgreSQL
-- keeps a filtered UNION ALL member as a subquery scan, which takes
-- no join parameters: the parent-edge and userset joins would lose
-- their index nested loops (a 3 ms page became 15 ms).
-- exact_replace mirrors check's exact-key read, where a contextual
-- row replaces the stored rows with the same key instead of joining
-- them — the only read where the two differ, and only once a
-- condition can tell the rows apart.
CREATE OR REPLACE FUNCTION fga._compiled_srcs(
  store_id uuid, model_id uuid, type_name text, relation_name text,
  cond_errcode text, exact_replace boolean
)
RETURNS text[]
LANGUAGE sql
IMMUTABLE PARALLEL SAFE
SET search_path = fga, pg_temp
AS $$
  SELECT ARRAY[
    ARRAY['fga.tuple', format('g.store%1$s%2$L::pg_catalog.uuid '
      'AND g.object_type%1$s%3$L AND g.relation%1$s%4$L%5$s',
      eq, store_id, type_name, relation_name,
      CASE WHEN exact_replace THEN format(
        ' AND (%1$s OR NOT EXISTS (SELECT FROM %2$s AS k WHERE '
        'k.object_type%3$sg.object_type AND k.object_id%3$sg.object_id '
        'AND k.relation%3$sg.relation '
        'AND k.subject_type%3$sg.subject_type '
        'AND k.subject_id%3$sg.subject_id '
        'AND k.subject_relation%3$sg.subject_relation))',
        fga._compiled_no_ctuples_sql(), ctx, eq)
      ELSE '' END)],
    ARRAY[ctx, format('NOT %s AND g.object_type%s%L '
      'AND g.relation%s%L', fga._compiled_no_ctuples_sql(),
      eq, type_name, eq, relation_name)]]
  FROM (SELECT ' OPERATOR(pg_catalog.=) ' AS eq,
    format('fga._compiled_ctx(%L::pg_catalog.uuid, '
      '%L::pg_catalog.uuid, p_contextual_tuples, %L)',
      store_id, model_id, cond_errcode) AS ctx) AS v;
$$;

-- Both sources of _compiled_srcs as one FROM item for alias g,
-- with cond added to each member. For arms that call another
-- relation's function, so the callee is inlined once, not once per
-- source. The planner still reaches the stored rows by index:
-- either the arm's own filters are constants pushed into the
-- members, or cond carries a LATERAL reference to the callee's row
-- — a join condition would not be pushed into a filtered member.
CREATE OR REPLACE FUNCTION fga._compiled_union(srcs text[], cond text)
RETURNS text
LANGUAGE sql
IMMUTABLE PARALLEL SAFE
SET search_path = fga, pg_temp
AS $$
  SELECT format('(SELECT g.object_id, g.subject_type, g.subject_id, '
    'g.subject_relation, g.condition_name, g.condition_context '
    'FROM %s AS g WHERE %s%s UNION ALL SELECT g.object_id, '
    'g.subject_type, g.subject_id, g.subject_relation, '
    'g.condition_name, g.condition_context FROM %s AS g WHERE %s%s)',
    srcs[1][1], srcs[1][2], cond, srcs[2][1], srcs[2][2], cond);
$$;

-- Condition evaluation for generated bodies, one function per way
-- a counterpart treats a condition error. Each evaluates through
-- the generic evaluator (_eval_condition: tuple context wins over
-- the request context per key, missing parameters are an error),
-- so a compiled answer and a generic one cannot disagree on a
-- condition — and conditions cost what they cost everywhere
-- (decision 18).
--
-- met: never raises (check's grant pass; an error counts as unmet).
CREATE OR REPLACE FUNCTION fga._compiled_met(
  store_id uuid, model_id uuid, cond_name text, tuple_ctx jsonb,
  req_ctx jsonb
)
RETURNS boolean
LANGUAGE sql
STABLE PARALLEL SAFE
SET search_path = fga, pg_temp
AS $$
  SELECT e.met FROM fga._eval_condition(
    store_id, model_id, cond_name, tuple_ctx, req_ctx) AS e;
$$;

-- err: the error, or NULL (check's held-error pass).
CREATE OR REPLACE FUNCTION fga._compiled_cond_err(
  store_id uuid, model_id uuid, cond_name text, tuple_ctx jsonb,
  req_ctx jsonb
)
RETURNS text
LANGUAGE sql
STABLE PARALLEL SAFE
SET search_path = fga, pg_temp
AS $$
  SELECT e.err FROM fga._eval_condition(
    store_id, model_id, cond_name, tuple_ctx, req_ctx) AS e;
$$;

-- cond: met, or raises the error (the list APIs, which fail the
-- request on any condition error they meet).
CREATE OR REPLACE FUNCTION fga._compiled_cond(
  store_id uuid, model_id uuid, cond_name text, tuple_ctx jsonb,
  req_ctx jsonb
)
RETURNS boolean
LANGUAGE plpgsql
STABLE PARALLEL SAFE
SET search_path = fga, pg_temp
AS $$
DECLARE
  ev record;
BEGIN
  SELECT * INTO ev FROM fga._eval_condition(
    store_id, model_id, cond_name, tuple_ctx, req_ctx);
  IF ev.err IS NOT NULL THEN
    RAISE EXCEPTION '%', ev.err USING ERRCODE = 'YF100';
  END IF;
  RETURN ev.met;
END;
$$;

-- false, or raises a held condition error: check's last step when
-- nothing granted.
CREATE OR REPLACE FUNCTION fga._compiled_held_error(err text)
RETURNS boolean
LANGUAGE plpgsql
STABLE PARALLEL SAFE
SET search_path = fga, pg_temp
AS $$
BEGIN
  IF err IS NOT NULL THEN
    RAISE EXCEPTION '%', err USING ERRCODE = 'YF100';
  END IF;
  RETURN false;
END;
$$;

-- Raised from a __subjects body that meets a wildcard grant whose
-- subject type has no registered source: the final list cannot be
-- written, and a partial one would be wrong. The argument is a
-- column of the grant row, so the call is evaluated only when such
-- a row exists.
CREATE OR REPLACE FUNCTION fga._compiled_no_source(
  subject_type text, grant_row text
)
RETURNS boolean
LANGUAGE plpgsql
STABLE PARALLEL SAFE
SET search_path = fga, pg_temp
AS $$
BEGIN
  RAISE EXCEPTION 'no subject source registered for type ''%'': '
    'a wildcard grant cannot be expanded into a list of subjects',
    subject_type USING ERRCODE = 'YF100',
    DETAIL = 'grant ' || grant_row;
END;
$$;

-- An emitter returns the three bodies of one relation. Each
-- strategy has its own emitter with this interface.

-- The delegated emitter: the generic resolver behind the generated
-- signature.
CREATE OR REPLACE FUNCTION fga._compiled_emit_delegated(
  store_id uuid, model_id uuid, type_name text, relation_name text,
  OUT objects_body text, OUT subjects_body text, OUT check_body text
)
LANGUAGE sql
IMMUTABLE PARALLEL SAFE
SET search_path = fga, pg_temp
AS $$
  SELECT
    format(
      'SELECT x FROM fga._compiled_objects(%L::pg_catalog.uuid, '
      '%L::pg_catalog.uuid, %L, %L, p_subject_type, p_subject_id, '
      'p_subject_relation, p_any_subject, p_context, '
      'p_contextual_tuples) AS x',
      store_id, model_id, type_name, relation_name),
    format(
      'SELECT x FROM fga._compiled_subjects(%L::pg_catalog.uuid, '
      '%L::pg_catalog.uuid, %L, %L, p_object, p_subject_type, '
      'p_subject_relation, p_context, p_contextual_tuples) AS x',
      store_id, model_id, type_name, relation_name),
    format(
      'SELECT fga._compiled_check(%L::pg_catalog.uuid, '
      '%L::pg_catalog.uuid, %L, %L, p_object, p_subject_type, '
      'p_subject_id, p_subject_relation, p_any_subject, p_context, '
      'p_contextual_tuples)',
      store_id, model_id, type_name, relation_name);
$$;

-- Internal helpers of the generator whose signatures evolve are
-- dropped by name first (see 050): CREATE OR REPLACE cannot change
-- a row type built from OUT parameters.
DO $$
DECLARE
  f record;
BEGIN
  FOR f IN
    SELECT p.oid::regprocedure AS sig
    FROM pg_proc p
    JOIN pg_namespace n ON n.oid = p.pronamespace
    WHERE n.nspname = 'fga'
      AND p.proname IN ('_compiled_leaf', '_compiled_setop_node',
                        '_compiled_place', '_compiled_ctx_set',
                        '_compiled_ctx_bool')
  LOOP
    EXECUTE 'DROP FUNCTION ' || f.sig;
  END LOOP;
END;
$$;

-- The contextual half of a check: whether any of the call's
-- contextual tuples satisfies one of conds, the check arms'
-- conditions on alias g over the parameters of a generated check
-- (p_object, p_subject_type, ...). A plain function call, not a
-- subplan, because a check body runs as its own statement when it
-- is not inlined, and every call starts every subplan of its plan,
-- run or not: one subplan per arm cost a page of nested checks 40%,
-- one per check still 20%, while a call that never runs costs
-- nothing. It runs only for calls that carry contextual tuples,
-- where planning one dynamic statement is affordable.
CREATE OR REPLACE FUNCTION fga._compiled_ctx_check(
  store_id uuid, model_id uuid, conds text,
  p_object uuid, p_subject_type text, p_subject_id uuid,
  p_subject_relation text, p_any_subject boolean, p_context jsonb,
  p_contextual_tuples jsonb
)
RETURNS boolean
LANGUAGE plpgsql
STABLE PARALLEL SAFE
SET search_path = fga, pg_temp
AS $$
DECLARE
  found_one boolean;
BEGIN
  EXECUTE format('SELECT EXISTS (SELECT FROM (SELECT $1 AS p_object, '
    '$2 AS p_subject_type, $3 AS p_subject_id, '
    '$4 AS p_subject_relation, $5 AS p_any_subject, $6 AS p_context, '
    '$7 AS p_contextual_tuples) AS p, fga._compiled_ctx(%L::uuid, '
    '%L::uuid, $7, ''YF127'') AS g WHERE %s)',
    store_id, model_id, conds)
  INTO found_one
  USING p_object, p_subject_type, p_subject_id, p_subject_relation,
    p_any_subject, p_context, p_contextual_tuples;
  RETURN found_one;
END;
$$;

-- The generated call to _compiled_ctx_check for one check, asking
-- about the subject sid / anys; NULL when there are no conditions.
CREATE OR REPLACE FUNCTION fga._compiled_ctx_exists(
  store_id uuid, model_id uuid, conds text[], sid text, anys text
)
RETURNS text
LANGUAGE sql
IMMUTABLE PARALLEL SAFE
SET search_path = fga, pg_temp
AS $$
  SELECT CASE WHEN cardinality(conds) > 0 THEN format(
    '(NOT %s AND fga._compiled_ctx_check(%L::pg_catalog.uuid, '
    '%L::pg_catalog.uuid, %L, p_object, p_subject_type, %s, '
    'p_subject_relation, %s, p_context, p_contextual_tuples))',
    fga._compiled_no_ctuples_sql(), store_id, model_id,
    array_to_string(conds, E'\n  OR '), sid, anys) END;
$$;

-- The arms of one leaf of a rewrite — a direct assignment ('this'),
-- a computed userset or a tuple-to-userset — for each kind: objs and
-- subs are SELECTs of one uuid column, checks boolean expressions,
-- check_errs SELECTs of the condition errors check holds back
-- until nothing grants. A wildcard grant's subjects are kept apart:
-- wild_subs lists them (over the registered subject source), wilds
-- only tests that the grant exists. One arm per way the leaf grants
-- and per source (_compiled_srcs): each direct restriction (plain,
-- wildcard, userset), the computed relation, each linked parent
-- type of a tuple-to-userset. Arms that reach another relation call
-- that relation's generated function, which PostgreSQL inlines in
-- turn.
--
-- Rows are read like the generic read helpers read them: stored
-- rows admitted by the relation's restrictions including the
-- condition binding (each arm names its subject type, relation and
-- condition), plus the call's contextual tuples. A conditioned
-- direct grant evaluates its condition only on rows that carry it,
-- after every other filter (OFFSET 0 keeps the planner from moving
-- the call ahead of them):
--   __objects / __subjects raise the first error they meet, as the
--     list APIs do;
--   __check counts an error as unmet and reports it through
--     check_errs, as check holds it until nothing grants.
-- Usersets and tuplesets are never conditioned here (the plan
-- delegates such relations), and arms that reach another relation
-- only reach relations that cannot raise.
--
-- sid and anys are the subject id and "any subject" expressions the
-- check arms test, so a __subjects body can ask a check about each
-- subject it lists. Every name in an arm is schema-qualified,
-- operators included, because the body runs under the caller's
-- search_path.
CREATE OR REPLACE FUNCTION fga._compiled_leaf(
  store_id uuid, model_id uuid, target text,
  type_name text, relation_name text, node jsonb,
  sid text, anys text,
  OUT objs text[], OUT subs text[], OUT checks text[],
  OUT ctx_checks text[], OUT check_errs text[], OUT wild_subs text[],
  OUT wilds text[]
)
LANGUAGE plpgsql
STABLE PARALLEL SAFE
SET search_path = fga, pg_temp
AS $$
DECLARE
  mid constant uuid := model_id;
  eq constant text := ' OPERATOR(pg_catalog.=) ';
  ne constant text := ' OPERATOR(pg_catalog.<>) ';
  nil constant text :=
    '''00000000-0000-0000-0000-000000000000''::pg_catalog.uuid';
  uncond constant text := '(g.condition_name IS NULL OR '
    'g.condition_name OPERATOR(pg_catalog.=) '''')';
  objects_args constant text := 'p_subject_type, p_subject_id, '
    'p_subject_relation, p_any_subject, p_context, '
    'p_contextual_tuples';
  check_args constant text := format('p_subject_type, %s, '
    'p_subject_relation, %s, p_context, p_contextual_tuples',
    sid, anys);
  -- ctx_checks are evaluated by _compiled_ctx_check, which binds
  -- the parameter names themselves (sid and anys are its arguments).
  ctx_args constant text := 'p_subject_type, p_subject_id, '
    'p_subject_relation, p_any_subject, p_context, '
    'p_contextual_tuples';
  subjects_args constant text := 'p_subject_type, '
    'p_subject_relation, p_context, p_contextual_tuples';
  -- Sources ({FROM item, base condition} pairs): list (YF100) for
  -- __objects / __subjects, chk (YF127) for __check, exact for
  -- check's exact-key read.
  list text[];
  chk text[];
  exact text[];
  x text[];
  rows_list text[];
  rows_chk text[];
  rows_wild text[];
  rows_of text;
  ref_objects text;
  ref_check text;
  ref_subjects text;
  match text;
  bind text;
  gate text;
  met text;
  sources jsonb;
  src text[];
  r record;
BEGIN
  objs := '{}';
  subs := '{}';
  checks := '{}';
  ctx_checks := '{}';
  check_errs := '{}';
  wild_subs := '{}';
  wilds := '{}';
  SELECT cs.subject_sources INTO sources
  FROM fga.compiled_store cs WHERE cs.store = store_id;

  IF node ? 'this' THEN
    list := fga._compiled_srcs(store_id, mid, type_name,
      relation_name, 'YF100', false);
    chk := fga._compiled_srcs(store_id, mid, type_name,
      relation_name, 'YF127', false);
    exact := fga._compiled_srcs(store_id, mid, type_name,
      relation_name, 'YF127', EXISTS (
        SELECT FROM fga.model_type_restriction tr
        WHERE tr.store = store_id AND tr.model_id = mid
          AND tr.type_name = _compiled_leaf.type_name
          AND tr.relation_name = _compiled_leaf.relation_name
          AND tr.condition_name <> ''));
    FOR r IN
      SELECT tr.subject_type, tr.subject_relation, tr.is_wildcard,
             tr.condition_name
      FROM fga.model_type_restriction tr
      WHERE tr.store = store_id AND tr.model_id = mid
        AND tr.type_name = _compiled_leaf.type_name
        AND tr.relation_name = _compiled_leaf.relation_name
      ORDER BY tr.ord
    LOOP
      match := format('g.subject_type%1$s%2$L AND '
        'g.subject_relation%1$s%3$L', eq, r.subject_type,
        r.subject_relation);
      bind := CASE WHEN r.condition_name = '' THEN uncond
        ELSE format('g.condition_name%s%L', eq, r.condition_name) END;
      gate := format('p_subject_type%1$s%2$L AND '
        'p_subject_relation%1$s''''', eq, r.subject_type);
      -- A condition call over a fenced row a(x, n, c), by function.
      met := format('%%s(%L::pg_catalog.uuid, %L::pg_catalog.uuid, '
        'a.n, a.c, p_context)', store_id, mid);
      rows_list := '{}';
      rows_chk := '{}';
      rows_wild := '{}';

      IF r.subject_relation <> '' THEN
        -- A userset grant: expand through the subject relation.
        ref_objects := fga._compiled_ref(target, r.subject_type,
          r.subject_relation, 'objects');
        ref_check := fga._compiled_ref(target, r.subject_type,
          r.subject_relation, 'check');
        ref_subjects := fga._compiled_ref(target, r.subject_type,
          r.subject_relation, 'subjects');
        objs := objs || format(
          'SELECT g.object_id FROM (SELECT x FROM %s(%s) AS x) AS c '
          'CROSS JOIN LATERAL %s AS g WHERE %s AND %s',
          ref_objects, objects_args, fga._compiled_union(list,
            ' AND g.subject_id' || eq || 'c.x'), match, bind);
        subs := subs || format(
          'SELECT x FROM %s AS g CROSS JOIN LATERAL %s(g.subject_id, '
          '%s) AS x WHERE g.object_id%sp_object AND %s AND %s',
          fga._compiled_union(list, ''), ref_subjects, subjects_args,
          eq, match, bind);
        checks := checks || format(
          'EXISTS (SELECT FROM %s AS g WHERE %s AND '
          'g.object_id%sp_object AND %s AND %s AND %s(g.subject_id, '
          '%s))', chk[1][1], chk[1][2], eq, match, bind, ref_check,
          check_args);
        ctx_checks := ctx_checks || format(
          '(%s AND g.object_id%sp_object AND %s AND %s AND '
          '%s(g.subject_id, %s))', chk[2][2], eq, match, bind,
          ref_check, ctx_args);
        CONTINUE;
      END IF;

      -- A plain or wildcard grant: check's exact-key read. The rows
      -- are listed as a(x, n, c) — the object (or subject) id, the
      -- condition name and its context.
      FOREACH x SLICE 1 IN ARRAY list LOOP
        IF r.is_wildcard THEN
          rows_list := rows_list || format(
            'SELECT g.object_id, g.condition_name, g.condition_context '
            'FROM %s AS g WHERE %s AND %s AND %s AND g.subject_id%s%s '
            'AND %s', x[1], x[2], match, bind, eq, nil, gate);
          rows_wild := rows_wild || format(
            'SELECT g.object_id, g.condition_name, g.condition_context '
            'FROM %s AS g WHERE %s AND g.object_id%sp_object AND %s '
            'AND %s AND g.subject_id%s%s AND %s',
            x[1], x[2], eq, match, bind, eq, nil, gate);
        ELSE
          rows_list := rows_list || format(
            'SELECT g.object_id, g.condition_name, g.condition_context '
            'FROM %s AS g WHERE %s AND %s AND %s '
            'AND g.subject_id%sp_subject_id AND %s '
            'AND NOT p_any_subject', x[1], x[2], match, bind, eq, gate);
          subs := subs || CASE WHEN r.condition_name = '' THEN format(
            'SELECT g.subject_id FROM %s AS g WHERE %s AND '
            'g.object_id%sp_object AND %s AND %s AND g.subject_id%s%s '
            'AND %s', x[1], x[2], eq, match, bind, ne, nil, gate)
          ELSE format('SELECT a.x FROM (SELECT g.subject_id, '
            'g.condition_name, g.condition_context FROM %s AS g WHERE '
            '%s AND g.object_id%sp_object AND %s AND %s AND '
            'g.subject_id%s%s AND %s OFFSET 0) AS a(x, n, c) WHERE %s',
            x[1], x[2], eq, match, bind, ne, nil, gate,
            format(met, 'fga._compiled_cond')) END;
        END IF;
      END LOOP;
      -- check's exact read: rows on the object with the subject's
      -- key (or the wildcard's), conditions over alias g.
      rows_of := format('g.object_id%s p_object AND %s AND %s '
        'AND g.subject_id%s%s AND %s%s', eq, match, bind, eq,
        CASE WHEN r.is_wildcard THEN nil ELSE sid END, gate,
        CASE WHEN r.is_wildcard THEN '' ELSE ' AND NOT ' || anys END);
      FOREACH x SLICE 1 IN ARRAY exact LOOP
        rows_chk := rows_chk || format(
          'SELECT g.condition_name, g.condition_context FROM %s AS g '
          'WHERE %s AND %s', x[1], x[2], rows_of);
      END LOOP;

      IF r.condition_name = '' THEN
        objs := objs || ARRAY(
          SELECT format('SELECT a.x FROM (%s) AS a(x, n, c)', q)
          FROM unnest(rows_list) AS q);
        checks := checks || format('EXISTS (%s)', rows_chk[1]);
        ctx_checks := ctx_checks || format('(%s AND g.object_id%s '
          'p_object AND %s AND %s AND g.subject_id%s%s AND %s%s)',
          exact[2][2], eq, match, bind, eq,
          CASE WHEN r.is_wildcard THEN nil ELSE 'p_subject_id' END, gate,
          CASE WHEN r.is_wildcard THEN '' ELSE ' AND NOT p_any_subject'
          END);
      ELSE
        -- Conditioned: the rows go through an OFFSET 0 fence and
        -- the condition filters them afterwards.
        objs := objs || format('SELECT a.x FROM (%s OFFSET 0) '
          'AS a(x, n, c) WHERE %s',
          array_to_string(rows_list, ' UNION ALL '),
          format(met, 'fga._compiled_cond'));
        checks := checks || format('EXISTS (SELECT FROM (%s OFFSET 0) '
          'AS a(n, c) WHERE %s)', array_to_string(rows_chk,
            ' UNION ALL '), format(met, 'fga._compiled_met'));
        check_errs := check_errs || format('SELECT %s FROM (%s '
          'OFFSET 0) AS a(n, c)', format(met, 'fga._compiled_cond_err'),
          array_to_string(rows_chk, ' UNION ALL '));
      END IF;

      -- The wildcard's final list: the registered subjects, or an
      -- error when a grant exists and no source is registered. A
      -- conditioned wildcard row raises its condition error first,
      -- whether or not the source has rows (list_users fails on any
      -- condition error it meets). wilds says only whether such a
      -- grant exists, for a set operation to combine.
      IF r.is_wildcard THEN
        rows_of := format('(%s OFFSET 0) AS a(x, n, c)',
          array_to_string(rows_wild, ' UNION ALL '));
        met := CASE WHEN r.condition_name = '' THEN 'true'
          ELSE format(met, 'fga._compiled_cond') END;
        wilds := wilds || format('(%s AND EXISTS (SELECT FROM %s '
          'WHERE %s))', gate, rows_of, met);
        src := fga._compiled_parse_source(sources ->> r.subject_type);
        IF src IS NOT NULL THEN
          IF r.condition_name <> '' THEN
            wild_subs := wild_subs || format(
              'SELECT NULL::pg_catalog.uuid FROM %s WHERE %s IS NULL',
              rows_of, met);
          END IF;
          wild_subs := wild_subs || format(
            'SELECT s.%I FROM %I.%I AS s WHERE %s AND EXISTS ('
            'SELECT FROM %s WHERE %s)',
            src[3], src[1], src[2], gate, rows_of, met);
        ELSE
          wild_subs := wild_subs || format(
            'SELECT a.x FROM %s WHERE CASE WHEN %s THEN '
            'fga._compiled_no_source(%L, a.x::pg_catalog.text) '
            'ELSE false END', rows_of, met, r.subject_type);
        END IF;
      END IF;
    END LOOP;

  ELSIF node ? 'computed_userset' THEN
    -- The same object, another relation.
    objs := objs || format('SELECT x FROM %s(%s) AS x',
      fga._compiled_ref(target, type_name,
        node -> 'computed_userset' ->> 'relation', 'objects'),
      objects_args);
    checks := checks || format('%s(p_object, %s)',
      fga._compiled_ref(target, type_name,
        node -> 'computed_userset' ->> 'relation', 'check'),
      check_args);
    subs := subs || format('SELECT x FROM %s(p_object, %s) AS x',
      fga._compiled_ref(target, type_name,
        node -> 'computed_userset' ->> 'relation', 'subjects'),
      subjects_args);

  ELSIF node ? 'tuple_to_userset' THEN
    -- Every parent type the tupleset admits that defines the
    -- computed relation (a parent type without it adds nothing, as
    -- in check).
    list := fga._compiled_srcs(store_id, mid, type_name,
      node -> 'tuple_to_userset' -> 'tupleset' ->> 'relation',
      'YF100', false);
    chk := fga._compiled_srcs(store_id, mid, type_name,
      node -> 'tuple_to_userset' -> 'tupleset' ->> 'relation',
      'YF127', false);
    FOR r IN
      SELECT DISTINCT tr.subject_type AS parent,
        node -> 'tuple_to_userset' -> 'computed_userset'
          ->> 'relation' AS rel
      FROM fga.model_type_restriction tr
      WHERE tr.store = store_id AND tr.model_id = mid
        AND tr.type_name = _compiled_leaf.type_name
        AND tr.relation_name
              = node -> 'tuple_to_userset' -> 'tupleset' ->> 'relation'
        AND tr.subject_relation = '' AND NOT tr.is_wildcard
        AND EXISTS (
          SELECT FROM fga.model_relation p
          WHERE p.store = store_id AND p.model_id = mid
            AND p.type_name = tr.subject_type
            AND p.relation_name = node -> 'tuple_to_userset'
                  -> 'computed_userset' ->> 'relation')
      ORDER BY 1
    LOOP
      match := format('g.subject_type%1$s%2$L AND '
        'g.subject_relation%1$s'''' AND g.subject_id%3$s%4$s AND %5$s',
        eq, r.parent, ne, nil, uncond);
      ref_objects := fga._compiled_ref(target, r.parent, r.rel,
        'objects');
      ref_check := fga._compiled_ref(target, r.parent, r.rel, 'check');
      ref_subjects := fga._compiled_ref(target, r.parent, r.rel,
        'subjects');
      objs := objs || format(
        'SELECT g.object_id FROM (SELECT x FROM %s(%s) AS x) AS c '
        'CROSS JOIN LATERAL %s AS g WHERE %s',
        ref_objects, objects_args, fga._compiled_union(list,
          ' AND g.subject_id' || eq || 'c.x'), match);
      subs := subs || format(
        'SELECT x FROM %s AS g CROSS JOIN LATERAL %s(g.subject_id, '
        '%s) AS x WHERE g.object_id%sp_object AND %s',
        fga._compiled_union(list, ''), ref_subjects, subjects_args,
        eq, match);
      checks := checks || format(
        'EXISTS (SELECT FROM %s AS g WHERE %s AND '
        'g.object_id%sp_object AND %s AND %s(g.subject_id, %s))',
        chk[1][1], chk[1][2], eq, match, ref_check, check_args);
      ctx_checks := ctx_checks || format(
        '(%s AND g.object_id%sp_object AND %s AND %s(g.subject_id, '
        '%s))', chk[2][2], eq, match, ref_check, ctx_args);
    END LOOP;
  END IF;
END;
$$;

-- The subject itself: T:o#R is a member of T:o#R, whatever the
-- rewrite (check answers it before reading anything).
CREATE OR REPLACE FUNCTION fga._compiled_self(
  type_name text, relation_name text,
  OUT obj text, OUT sub text, OUT chk text
)
LANGUAGE sql
IMMUTABLE PARALLEL SAFE
SET search_path = fga, pg_temp
AS $$
  SELECT
    format('SELECT p_subject_id WHERE p_subject_type%1$s%2$L '
      'AND p_subject_relation%1$s%3$L AND NOT p_any_subject',
      ' OPERATOR(pg_catalog.=) ', type_name, relation_name),
    format('SELECT p_object WHERE p_subject_type%1$s%2$L '
      'AND p_subject_relation%1$s%3$L',
      ' OPERATOR(pg_catalog.=) ', type_name, relation_name),
    format('(p_subject_type%1$s%2$L AND p_subject_relation%1$s%3$L '
      'AND NOT p_any_subject AND p_subject_id%1$sp_object)',
      ' OPERATOR(pg_catalog.=) ', type_name, relation_name);
$$;

-- The statement a body that cannot be inlined starts with, so the
-- planner gives up inlining it before analysing it (see
-- _compiled_assemble).
CREATE OR REPLACE FUNCTION fga._compiled_no_inline()
RETURNS text
LANGUAGE sql
IMMUTABLE PARALLEL SAFE
SET search_path = fga, pg_temp
AS $$
  SELECT E'SELECT;\n';
$$;

-- The three bodies around a relation's arms: validation first (it
-- raises, never filters) in each counterpart's order — contextual
-- tuples before the subject for the list APIs, after it for check
-- — then the union of the arms. A check with held condition errors
-- raises the first of them when no arm grants.
--
-- A check body starts with an empty statement (_compiled_no_inline).
-- PostgreSQL never inlines a check that reads tuples (its EXISTS
-- stops it), but finds that out only after parsing and analysing
-- the body, on every planning of the statement calling it; with two
-- statements it stops after the raw parse. A plpgsql EXECUTE plans
-- its statement on every call (dispatch calls __check that way), and
-- on the tenant bench a check so called went from 0.37 ms to 0.21.
CREATE OR REPLACE FUNCTION fga._compiled_assemble(
  store_id uuid, model_id uuid,
  objs text[], subs text[], checks text[], check_errs text[],
  OUT objects_body text, OUT subjects_body text, OUT check_body text
)
LANGUAGE sql
IMMUTABLE PARALLEL SAFE
SET search_path = fga, pg_temp
AS $$
  SELECT
    format('SELECT NULL::pg_catalog.uuid WHERE NOT %s'
      || E'\nUNION\nSELECT NULL::pg_catalog.uuid WHERE '
      'fga._compiled_sid(p_subject_id, p_any_subject, '
      'p_subject_relation) IS NULL', ctx_list)
    || (SELECT string_agg(format(
         E'\nUNION\nSELECT a.x FROM (%s) AS a(x)', a), '' ORDER BY i)
        FROM unnest(objs) WITH ORDINALITY AS u(a, i)),
    format('SELECT NULL::pg_catalog.uuid WHERE NOT %s'
      || E'\nUNION\nSELECT NULL::pg_catalog.uuid WHERE '
      'fga._compiled_oid(p_object) IS NULL', ctx_list)
    || (SELECT string_agg(format(
         E'\nUNION\nSELECT a.x FROM (%s) AS a(x)', a), '' ORDER BY i)
        FROM unnest(subs) WITH ORDINALITY AS u(a, i)),
    format('%sSELECT fga._compiled_sid(p_subject_id, p_any_subject, '
      'p_subject_relation) IS NOT NULL AND fga._compiled_oid(p_object) '
      'IS NOT NULL AND %s AND %s', fga._compiled_no_inline(), ctx_check,
      CASE
      WHEN cardinality(check_errs) = 0
      THEN format('(%s)', array_to_string(checks, E'\n  OR '))
      ELSE format(E'CASE WHEN %s THEN true\n  ELSE '
        'fga._compiled_held_error((SELECT pg_catalog.min(e.x) FROM '
        '(%s) AS e(x))) END',
        array_to_string(checks, E'\n  OR '),
        array_to_string(check_errs, E'\n  UNION ALL ')) END)
  FROM (SELECT
    format('(%s OR fga._compiled_ctx_valid(%L::pg_catalog.uuid, '
      '%L::pg_catalog.uuid, p_contextual_tuples, ''YF100''))',
      fga._compiled_no_ctuples_sql(), store_id, model_id) AS ctx_list,
    format('(%s OR fga._compiled_ctx_valid(%L::pg_catalog.uuid, '
      '%L::pg_catalog.uuid, p_contextual_tuples, ''YF127''))',
      fga._compiled_no_ctuples_sql(), store_id, model_id) AS ctx_check
  ) AS v;
$$;

-- The places a flattened relation reaches. A place is where a
-- subject can be granted: a path of hops from the relation's object
-- — tuple-to-userset edges (tupleset rows to a parent) and userset
-- grants (rows naming T:o#R, continuing at R on T) — and every
-- relation reached at its end through computed usersets. Relations
-- of one place share its path, so the whole ladder a relation
-- reaches becomes one fixed join per place, however many routes
-- lead there: env#can_view on a four-level tenant hierarchy is four
-- places (the leaf, its project, its account, the platform), where
-- composing the reached relations' functions plans each callee once
-- per route to it.
--
-- A hop is {t, st, sr} plus ts for a tuple-to-userset (the tupleset
-- relation); a userset hop's row relations are the relations of the
-- place before it that admit st#sr. A set operation reached on the
-- way is not walked into: it is kept in opaque, and answered by its
-- own generated function. Only flattened and conditioned relations
-- come here, so the walk meets no cycle and ends: the plan keeps
-- them under 24 dispatches, and the bound on the path length only
-- guards the walk itself.
CREATE OR REPLACE FUNCTION fga._compiled_places(
  store_id uuid, model_id uuid, type_name text, relation_name text
)
RETURNS TABLE (path jsonb, place_type text, rels text[],
               opaque text[])
LANGUAGE sql
STABLE PARALLEL SAFE
SET search_path = fga, pg_temp
AS $$
  WITH RECURSIVE
  rel AS (
    SELECT r.type_name, r.relation_name, r.rewrite, r.needs_check
    FROM fga.model_relation r
    WHERE r.store = store_id AND r.model_id = _compiled_places.model_id
  ),
  restriction AS (
    SELECT tr.* FROM fga.model_type_restriction tr
    WHERE tr.store = store_id
      AND tr.model_id = _compiled_places.model_id
  ),
  w(path, t, r) AS (
    SELECT '[]'::jsonb, _compiled_places.type_name,
           _compiled_places.relation_name
    UNION
    SELECT n.path, n.t, n.r
    FROM w
    JOIN rel ON rel.type_name = w.t AND rel.relation_name = w.r
    CROSS JOIN LATERAL (
      SELECT w.path, w.t, nd -> 'computed_userset' ->> 'relation'
      FROM fga._rewrite_nodes(rel.rewrite) AS nd
      WHERE nd ? 'computed_userset'
      UNION ALL
      SELECT w.path || jsonb_build_array(jsonb_build_object(
               't', w.t,
               'ts', nd -> 'tuple_to_userset' -> 'tupleset'
                       ->> 'relation',
               'st', tr.subject_type, 'sr', '')),
             tr.subject_type,
             nd -> 'tuple_to_userset' -> 'computed_userset'
               ->> 'relation'
      FROM fga._rewrite_nodes(rel.rewrite) AS nd
      JOIN restriction tr
        ON tr.type_name = w.t
       AND tr.relation_name
             = nd -> 'tuple_to_userset' -> 'tupleset' ->> 'relation'
      WHERE nd ? 'tuple_to_userset'
        AND tr.subject_relation = '' AND NOT tr.is_wildcard
        AND EXISTS (
          SELECT FROM rel p
          WHERE p.type_name = tr.subject_type
            AND p.relation_name = nd -> 'tuple_to_userset'
                  -> 'computed_userset' ->> 'relation')
      UNION ALL
      SELECT w.path || jsonb_build_array(jsonb_build_object(
               't', w.t, 'st', tr.subject_type,
               'sr', tr.subject_relation)),
             tr.subject_type, tr.subject_relation
      FROM restriction tr
      WHERE tr.type_name = w.t AND tr.relation_name = w.r
        AND tr.subject_relation <> ''
        AND EXISTS (
          SELECT FROM fga._rewrite_nodes(rel.rewrite) AS nd
          WHERE nd ? 'this')
    ) AS n(path, t, r)
    WHERE NOT rel.needs_check
      AND jsonb_array_length(w.path) < 32
  )
  SELECT w.path, w.t,
    coalesce(array_agg(DISTINCT w.r ORDER BY w.r)
               FILTER (WHERE NOT rel.needs_check), '{}'),
    coalesce(array_agg(DISTINCT w.r ORDER BY w.r)
               FILTER (WHERE rel.needs_check), '{}')
  FROM w
  JOIN rel ON rel.type_name = w.t AND rel.relation_name = w.r
  GROUP BY w.path, w.t;
$$;

-- "col = 'a'" or "col = ANY ('{a,b}')", qualified.
CREATE OR REPLACE FUNCTION fga._compiled_in(col text, vals text[])
RETURNS text
LANGUAGE sql
IMMUTABLE PARALLEL SAFE
SET search_path = fga, pg_temp
AS $$
  SELECT CASE WHEN cardinality(vals) = 1
    THEN format('%s OPERATOR(pg_catalog.=) %L', col, vals[1])
    ELSE format('%s OPERATOR(pg_catalog.=) ANY (%L::pg_catalog.text[])',
                col, vals) END;
$$;

-- A chain of tuple reads as "FROM … WHERE …": aliases[i] reads the
-- rows satisfying conds[i], which may name earlier aliases (and
-- head, a FROM item placed first). Two sources:
--   stored  fga.tuple only, joined freely — the body a call without
--           contextual tuples runs, so the planner orders the joins;
--   ctx     each read the union of fga.tuple and k, the call's
--           validated contextual tuples, as a LATERAL subquery so
--           the conditions on earlier aliases reach the index. Only
--           the dynamic statement a call with contextual tuples
--           runs uses it (it defines k). exact[i] makes a read
--           check's exact-key read: a contextual row replaces the
--           stored rows with its key.
CREATE OR REPLACE FUNCTION fga._compiled_chain(
  store_id uuid, ctx boolean, head text, aliases text[],
  conds text[], exact boolean[], extra text
)
RETURNS text
LANGUAGE plpgsql
IMMUTABLE PARALLEL SAFE
SET search_path = fga, pg_temp
AS $$
DECLARE
  eq constant text := ' OPERATOR(pg_catalog.=) ';
  cols constant text := '%1$s.object_type, %1$s.object_id, '
    '%1$s.relation, %1$s.subject_type, %1$s.subject_id, '
    '%1$s.subject_relation, %1$s.condition_name, '
    '%1$s.condition_context';
  items text[] := CASE WHEN head IS NULL THEN '{}'
                       ELSE ARRAY[head] END;
  wheres text[] := '{}';
  a text;
BEGIN
  FOR i IN 1 .. coalesce(cardinality(aliases), 0) LOOP
    a := aliases[i];
    IF NOT ctx THEN
      items := items || format('fga.tuple AS %s', a);
      wheres := wheres || format('%s.store%s%L::pg_catalog.uuid AND %s',
        a, eq, store_id, conds[i]);
      CONTINUE;
    END IF;
    items := items || format(
      CASE WHEN cardinality(items) = 0 THEN '(%s) AS %s'
           ELSE 'CROSS JOIN LATERAL (%s) AS %s' END,
      format('SELECT ' || cols || ' FROM fga.tuple AS %1$s WHERE '
        '%1$s.store%2$s%3$L::pg_catalog.uuid AND %4$s%5$s UNION ALL '
        'SELECT ' || cols || ' FROM k AS %1$s WHERE %4$s',
        a, eq, store_id, conds[i],
        CASE WHEN exact[i] THEN format(' AND NOT EXISTS (SELECT FROM '
          'k AS kx WHERE kx.object_type%2$s%1$s.object_type AND '
          'kx.object_id%2$s%1$s.object_id AND '
          'kx.relation%2$s%1$s.relation AND '
          'kx.subject_type%2$s%1$s.subject_type AND '
          'kx.subject_id%2$s%1$s.subject_id AND '
          'kx.subject_relation%2$s%1$s.subject_relation)', a, eq)
        ELSE '' END),
      a);
  END LOOP;
  IF NOT ctx THEN
    items := ARRAY[array_to_string(items, ', ')];
  END IF;
  wheres := wheres || extra;
  RETURN format('FROM %s WHERE %s', array_to_string(items, ' '),
    coalesce(nullif(array_to_string(wheres, ' AND '), ''), 'true'));
END;
$$;

-- The arms of one place, read from one source (_compiled_chain):
-- objs and subs SELECT one uuid column; check_arms are SELECT 1
-- rows for one EXISTS over all of them, check_bools boolean terms
-- outside it, check_errs SELECTs of the condition errors check holds
-- until nothing grants. Each place answers for
--   itself    T:o#R for every relation R of the place (check answers
--             a subject asking about itself before reading anything);
--   grants    the direct restrictions of its relations, one arm per
--             (subject type, wildcard, condition) with the relations
--             that admit it, read like the generic read helpers
--             read them (the condition binding included);
--   opaque    a set operation, through its generated function.
-- Rows on the path are unconditioned (the plan delegates a relation
-- reaching a conditioned userset or tupleset); only the compiled
-- relation's own grants can carry conditions, evaluated after every
-- other filter (OFFSET 0 keeps the call behind them), as the leaf
-- arms of _compiled_leaf evaluate them.
CREATE OR REPLACE FUNCTION fga._compiled_place(
  store_id uuid, model_id uuid, target text, path jsonb,
  place_type text, rels text[], opaque text[], prefixes jsonb,
  ctx boolean,
  OUT objs text[], OUT subs text[], OUT check_arms text[],
  OUT check_bools text[], OUT check_errs text[]
)
LANGUAGE plpgsql
STABLE PARALLEL SAFE
SET search_path = fga, pg_temp
AS $$
DECLARE
  mid constant uuid := model_id;
  eq constant text := ' OPERATOR(pg_catalog.=) ';
  ne constant text := ' OPERATOR(pg_catalog.<>) ';
  nil constant text :=
    '''00000000-0000-0000-0000-000000000000''::pg_catalog.uuid';
  n constant integer := jsonb_array_length(path);
  objects_args constant text := 'p_subject_type, p_subject_id, '
    'p_subject_relation, p_any_subject, p_context, '
    'p_contextual_tuples';
  subjects_args constant text := 'p_subject_type, '
    'p_subject_relation, p_context, p_contextual_tuples';
  self_gate constant text := format('p_subject_type%s%L AND %s', eq,
    place_type, fga._compiled_in('p_subject_relation', rels || opaque));
  hop jsonb;
  pre jsonb := '[]';
  hop_rels text[];
  base text;
  -- The path's reads: up from p_object (check, subjects) and down to
  -- the root object (objects; the last one is linked to the place's
  -- object by the caller of the chain).
  up_al text[] := '{}';
  up text[] := '{}';
  dn_al text[] := '{}';
  dn text[] := '{}';
  no_ex boolean[] := '{}';
  top text := CASE WHEN n = 0 THEN 'p_object'
                   ELSE format('e%s.subject_id', n) END;
  leaf text := CASE WHEN n = 0 THEN 'g.object_id' ELSE 'e1.object_id' END;
  sources jsonb;
  src text[];
  gate text;
  gcond text;
  rows_of text;
  met text;
  q text;
  r record;
BEGIN
  objs := '{}';
  subs := '{}';
  check_arms := '{}';
  check_bools := '{}';
  check_errs := '{}';
  SELECT cs.subject_sources INTO sources
  FROM fga.compiled_store cs WHERE cs.store = store_id;

  FOR i IN 1 .. n LOOP
    hop := path -> (i - 1);
    hop_rels := CASE WHEN hop ? 'ts' THEN ARRAY[hop ->> 'ts'] ELSE ARRAY(
      SELECT DISTINCT tr.relation_name
      FROM fga.model_type_restriction tr
      JOIN fga.model_relation mr
        ON mr.store = tr.store AND mr.model_id = tr.model_id
       AND mr.type_name = tr.type_name
       AND mr.relation_name = tr.relation_name
      WHERE tr.store = store_id AND tr.model_id = mid
        AND tr.type_name = hop ->> 't'
        AND tr.relation_name IN (
          SELECT jsonb_array_elements_text(prefixes -> (pre::text)))
        AND tr.subject_type = hop ->> 'st'
        AND tr.subject_relation = hop ->> 'sr'
        AND EXISTS (SELECT FROM fga._rewrite_nodes(mr.rewrite) AS nd
                    WHERE nd ? 'this')
      ORDER BY 1) END;
    base := format('e%1$s.object_type%2$s%3$L AND %4$s AND '
      'e%1$s.subject_type%2$s%5$L AND e%1$s.subject_relation%2$s%6$L '
      'AND (e%1$s.condition_name IS NULL OR '
      'e%1$s.condition_name%2$s'''')%7$s',
      i, eq, hop ->> 't', fga._compiled_in(format('e%s.relation', i),
        hop_rels), hop ->> 'st', hop ->> 'sr',
      CASE WHEN hop ? 'ts' THEN format(' AND e%s.subject_id%s%s', i,
        ne, nil) ELSE '' END);
    up_al := up_al || ('e' || i);
    up := up || (base || format(' AND e%s.object_id%s%s', i, eq,
      CASE WHEN i = 1 THEN 'p_object'
           ELSE format('e%s.subject_id', i - 1) END));
    -- Down: e(n) first, each e(i) linked to e(i+1) below it.
    dn_al := ('e' || i) || dn_al;
    dn := (base || CASE WHEN i < n THEN format(
      ' AND e%s.subject_id%se%s.object_id', i, eq, i + 1) ELSE '' END)
      || dn;
    no_ex := no_ex || false;
    pre := pre || jsonb_build_array(hop);
  END LOOP;

  -- Itself.
  IF n = 0 THEN
    objs := objs || format('SELECT p_subject_id WHERE %s AND NOT '
      'p_any_subject', self_gate);
    subs := subs || format('SELECT p_object WHERE %s', self_gate);
    check_bools := check_bools || format('(%s AND NOT p_any_subject '
      'AND p_subject_id%sp_object)', self_gate, eq);
  ELSE
    objs := objs || format('SELECT e1.object_id %s',
      fga._compiled_chain(store_id, ctx, NULL, dn_al,
        ARRAY[dn[1] || format(' AND e%s.subject_id%sp_subject_id', n,
          eq)] || dn[2:], no_ex, self_gate || ' AND NOT p_any_subject'));
    subs := subs || format('SELECT %s %s', top,
      fga._compiled_chain(store_id, ctx, NULL, up_al, up, no_ex,
        self_gate));
    check_arms := check_arms || format('SELECT 1 %s',
      fga._compiled_chain(store_id, ctx, NULL, up_al, up, no_ex,
        format('%s AND NOT p_any_subject AND %s%sp_subject_id',
          self_gate, top, eq)));
  END IF;

  -- Direct grants: one arm per (subject type, wildcard, condition).
  FOR r IN
    SELECT tr.subject_type AS st, tr.is_wildcard AS wild,
      tr.condition_name AS cond,
      array_agg(DISTINCT tr.relation_name ORDER BY tr.relation_name)
        AS grels,
      bool_or(EXISTS (
        SELECT FROM fga.model_type_restriction c
        WHERE c.store = tr.store AND c.model_id = tr.model_id
          AND c.type_name = tr.type_name
          AND c.relation_name = tr.relation_name
          AND c.condition_name <> '')) AS exact
    FROM fga.model_type_restriction tr
    JOIN fga.model_relation mr
      ON mr.store = tr.store AND mr.model_id = tr.model_id
     AND mr.type_name = tr.type_name
     AND mr.relation_name = tr.relation_name
    WHERE tr.store = store_id AND tr.model_id = mid
      AND tr.type_name = place_type
      AND tr.relation_name = ANY (rels)
      AND tr.subject_relation = ''
      AND EXISTS (SELECT FROM fga._rewrite_nodes(mr.rewrite) AS nd
                  WHERE nd ? 'this')
    GROUP BY 1, 2, 3
    ORDER BY 1, 2, 3
  LOOP
    gcond := format('g.object_type%1$s%2$L AND %3$s AND '
      'g.subject_type%1$s%4$L AND g.subject_relation%1$s'''' AND %5$s',
      eq, place_type, fga._compiled_in('g.relation', r.grels), r.st,
      CASE WHEN r.cond = '' THEN '(g.condition_name IS NULL OR '
        'g.condition_name OPERATOR(pg_catalog.=) '''')'
      ELSE format('g.condition_name%s%L', eq, r.cond) END);
    gate := format('p_subject_type%1$s%2$L AND '
      'p_subject_relation%1$s''''', eq, r.st);
    met := format('%%s(%L::pg_catalog.uuid, %L::pg_catalog.uuid, '
      'a.n, a.c, p_context)', store_id, mid);

    -- Objects: from the grant down the path to the root object.
    q := fga._compiled_chain(store_id, ctx, NULL,
      ARRAY['g'] || dn_al,
      ARRAY[gcond || format(' AND g.subject_id%s%s', eq,
        CASE WHEN r.wild THEN nil ELSE 'p_subject_id' END)]
      || CASE WHEN n = 0 THEN dn ELSE ARRAY[dn[1] || format(
        ' AND e%s.subject_id%sg.object_id', n, eq)] || dn[2:] END,
      ARRAY[false] || no_ex,
      gate || CASE WHEN r.wild THEN '' ELSE ' AND NOT p_any_subject' END);
    objs := objs || CASE WHEN r.cond = '' THEN format('SELECT %s %s',
        leaf, q)
      ELSE format('SELECT a.x FROM (SELECT %s, g.condition_name, '
        'g.condition_context %s OFFSET 0) AS a(x, n, c) WHERE %s',
        leaf, q, format(met, 'fga._compiled_cond')) END;

    -- Check: up the path to the grant.
    q := fga._compiled_chain(store_id, ctx, NULL, up_al || 'g'::text,
      up || (gcond || format(' AND g.object_id%s%s AND g.subject_id%s%s',
        eq, top, eq, CASE WHEN r.wild THEN nil ELSE 'p_subject_id' END)),
      no_ex || r.exact,
      gate || CASE WHEN r.wild THEN '' ELSE ' AND NOT p_any_subject' END);
    IF r.cond = '' THEN
      check_arms := check_arms || format('SELECT 1 %s', q);
    ELSE
      check_arms := check_arms || format('SELECT 1 FROM (SELECT '
        'g.condition_name, g.condition_context %s OFFSET 0) AS a(n, c) '
        'WHERE %s', q, format(met, 'fga._compiled_met'));
      check_errs := check_errs || format('SELECT %s FROM (SELECT '
        'g.condition_name, g.condition_context %s OFFSET 0) AS a(n, c)',
        format(met, 'fga._compiled_cond_err'), q);
    END IF;

    -- Subjects: up the path, then the grant's subjects.
    q := fga._compiled_chain(store_id, ctx, NULL, up_al || 'g'::text,
      up || (gcond || format(' AND g.object_id%s%s AND g.subject_id%s%s',
        eq, top, CASE WHEN r.wild THEN eq ELSE ne END, nil)),
      no_ex || false, gate);
    IF NOT r.wild THEN
      subs := subs || CASE WHEN r.cond = '' THEN format(
          'SELECT g.subject_id %s', q)
        ELSE format('SELECT a.x FROM (SELECT g.subject_id, '
          'g.condition_name, g.condition_context %s OFFSET 0) '
          'AS a(x, n, c) WHERE %s', q, format(met, 'fga._compiled_cond'))
        END;
      CONTINUE;
    END IF;
    -- A wildcard's final list: the registered subjects, or an error
    -- when a grant exists and no source is registered. A conditioned
    -- wildcard row raises its condition error first, whether or not
    -- the source has rows (list_users fails on any condition error
    -- it meets).
    rows_of := format('(SELECT g.object_id, g.condition_name, '
      'g.condition_context %s OFFSET 0) AS a(x, n, c)', q);
    met := CASE WHEN r.cond = '' THEN 'true'
      ELSE format(met, 'fga._compiled_cond') END;
    src := fga._compiled_parse_source(sources ->> r.st);
    IF src IS NOT NULL THEN
      IF r.cond <> '' THEN
        subs := subs || format('SELECT NULL::pg_catalog.uuid FROM %s '
          'WHERE %s IS NULL', rows_of, met);
      END IF;
      subs := subs || format('SELECT s.%I FROM %I.%I AS s WHERE %s AND '
        'EXISTS (SELECT FROM %s WHERE %s)',
        src[3], src[1], src[2], gate, rows_of, met);
    ELSE
      subs := subs || format('SELECT a.x FROM %s WHERE CASE WHEN %s '
        'THEN fga._compiled_no_source(%L, a.x::pg_catalog.text) '
        'ELSE false END', rows_of, met, r.st);
    END IF;
  END LOOP;

  -- Set operations reached here answer through their own functions.
  FOR r IN SELECT x AS rel FROM unnest(opaque) AS x ORDER BY 1 LOOP
    IF n = 0 THEN
      objs := objs || format('SELECT o.x FROM %s(%s) AS o(x)',
        fga._compiled_ref(target, place_type, r.rel, 'objects'),
        objects_args);
      subs := subs || format('SELECT o.x FROM %s(p_object, %s) AS o(x)',
        fga._compiled_ref(target, place_type, r.rel, 'subjects'),
        subjects_args);
      check_bools := check_bools || format('%s(p_object, '
        'p_subject_type, p_subject_id, p_subject_relation, '
        'p_any_subject, p_context, p_contextual_tuples)',
        fga._compiled_ref(target, place_type, r.rel, 'check'));
      CONTINUE;
    END IF;
    objs := objs || format('SELECT e1.object_id %s',
      fga._compiled_chain(store_id, ctx, format(
        '(SELECT x FROM %s(%s) AS x) AS o(x)', fga._compiled_ref(target,
          place_type, r.rel, 'objects'), objects_args), dn_al,
        ARRAY[dn[1] || format(' AND e%s.subject_id%so.x', n, eq)]
        || dn[2:], no_ex, NULL));
    subs := subs || format('SELECT o.x FROM (SELECT %s AS t %s) AS q '
      'CROSS JOIN LATERAL %s(q.t, %s) AS o(x)', top,
      fga._compiled_chain(store_id, ctx, NULL, up_al, up, no_ex, NULL),
      fga._compiled_ref(target, place_type, r.rel, 'subjects'),
      subjects_args);
    check_arms := check_arms || format('SELECT 1 %s',
      fga._compiled_chain(store_id, ctx, NULL, up_al, up, no_ex,
        format('%s(%s, p_subject_type, p_subject_id, '
          'p_subject_relation, p_any_subject, p_context, '
          'p_contextual_tuples)', fga._compiled_ref(target, place_type,
            r.rel, 'check'), top)));
  END LOOP;
END;
$$;

-- A call's contextual tuples are answered by a dynamic statement:
-- the same arms over fga.tuple and the call's validated contextual
-- tuples (k), run only when a call carries some, and stored in
-- fga.compiled_contextual under the function's own key. The
-- statement binds the generated function's parameters as $1 .. $7,
-- columns of p.
CREATE OR REPLACE FUNCTION fga._compiled_ctx_find(
  store_id uuid, model_id uuid, type_name text, relation_name text,
  kind text
)
RETURNS text
LANGUAGE plpgsql
STABLE PARALLEL SAFE
SET search_path = fga, pg_temp
AS $$
DECLARE
  stmt text;
BEGIN
  SELECT c.stmt INTO stmt FROM fga.compiled_contextual c
  WHERE c.store = store_id AND c.model_id = _compiled_ctx_find.model_id
    AND c.type_name = _compiled_ctx_find.type_name
    AND c.relation_name = _compiled_ctx_find.relation_name
    AND c.kind = _compiled_ctx_find.kind;
  IF stmt IS NULL THEN
    RAISE EXCEPTION 'compiled relations: no contextual-tuple '
      'statement registered for %#% (%), model %', type_name,
      relation_name, kind, model_id USING ERRCODE = 'internal_error';
  END IF;
  RETURN stmt;
END;
$$;

CREATE OR REPLACE FUNCTION fga._compiled_ctx_set(
  store_id uuid, model_id uuid, type_name text, relation_name text,
  kind text, p_object uuid, p_subject_type text, p_subject_id uuid,
  p_subject_relation text, p_any_subject boolean, p_context jsonb,
  p_contextual_tuples jsonb
)
RETURNS SETOF uuid
LANGUAGE plpgsql
STABLE PARALLEL SAFE
COST 1 ROWS 10
SET search_path = fga, pg_temp
AS $$
BEGIN
  RETURN QUERY EXECUTE fga._compiled_ctx_find(store_id, model_id,
    type_name, relation_name, kind)
  USING p_object, p_subject_type, p_subject_id, p_subject_relation,
    p_any_subject, p_context, p_contextual_tuples;
END;
$$;

CREATE OR REPLACE FUNCTION fga._compiled_ctx_bool(
  store_id uuid, model_id uuid, type_name text, relation_name text,
  p_object uuid, p_subject_type text, p_subject_id uuid,
  p_subject_relation text, p_any_subject boolean, p_context jsonb,
  p_contextual_tuples jsonb
)
RETURNS boolean
LANGUAGE plpgsql
STABLE PARALLEL SAFE
COST 1
SET search_path = fga, pg_temp
AS $$
DECLARE
  answer boolean;
BEGIN
  EXECUTE fga._compiled_ctx_find(store_id, model_id, type_name,
    relation_name, 'check')
  INTO answer
  USING p_object, p_subject_type, p_subject_id, p_subject_relation,
    p_any_subject, p_context, p_contextual_tuples;
  RETURN answer;
END;
$$;

-- The dynamic statement around one kind's arms (see _compiled_ctx_set):
-- k holds the call's contextual tuples once, p its parameters.
CREATE OR REPLACE FUNCTION fga._compiled_ctx_stmt(
  store_id uuid, model_id uuid, cond_errcode text, sel text,
  lateral_from text
)
RETURNS text
LANGUAGE sql
IMMUTABLE PARALLEL SAFE
SET search_path = fga, pg_temp
AS $$
  SELECT format('WITH k AS MATERIALIZED (SELECT * FROM '
    'fga._compiled_ctx(%L::pg_catalog.uuid, %L::pg_catalog.uuid, $7, '
    '%L)) SELECT %s FROM (SELECT $1::pg_catalog.uuid AS p_object, '
    '$2::pg_catalog.text AS p_subject_type, '
    '$3::pg_catalog.uuid AS p_subject_id, '
    '$4::pg_catalog.text AS p_subject_relation, '
    '$5::pg_catalog.bool AS p_any_subject, '
    '$6::pg_catalog.jsonb AS p_context, '
    '$7::pg_catalog.jsonb AS p_contextual_tuples) AS p%s',
    store_id, model_id, cond_errcode, sel, coalesce(lateral_from, ''));
$$;

-- The check expression over one source's arms: the terms outside,
-- one EXISTS over every arm, and the first held condition error when
-- nothing grants.
CREATE OR REPLACE FUNCTION fga._compiled_check_expr(
  bools text[], arms text[], errs text[]
)
RETURNS text
LANGUAGE sql
IMMUTABLE PARALLEL SAFE
SET search_path = fga, pg_temp
AS $$
  SELECT CASE WHEN cardinality(errs) = 0 THEN format('(%s)', core)
    ELSE format(E'CASE WHEN %s THEN true\n  ELSE '
      'fga._compiled_held_error((SELECT pg_catalog.min(e.x) FROM '
      '(%s) AS e(x))) END', core,
      array_to_string(errs, E'\n  UNION ALL ')) END
  FROM (SELECT coalesce(nullif(array_to_string(bools
    || CASE WHEN cardinality(arms) > 0 THEN format(E'EXISTS (%s)',
         array_to_string(arms, E'\n  UNION ALL ')) END,
    E'\n  OR '), ''), 'false') AS core) AS v;
$$;

-- Every arm of a flattened relation, over one source
-- (_compiled_chain): the objects and subjects arms, and the check
-- expression.
CREATE OR REPLACE FUNCTION fga._compiled_flat_arms(
  store_id uuid, model_id uuid, target text,
  type_name text, relation_name text, ctx boolean,
  OUT objs text[], OUT subs text[], OUT check_expr text
)
LANGUAGE plpgsql
STABLE PARALLEL SAFE
SET search_path = fga, pg_temp
AS $$
DECLARE
  prefixes jsonb := '{}';
  pl record;
  s record;
  arms text[] := '{}';
  bools text[] := '{}';
  errs text[] := '{}';
BEGIN
  objs := '{}';
  subs := '{}';
  FOR pl IN
    SELECT * FROM fga._compiled_places(store_id, model_id,
      _compiled_flat_arms.type_name,
      _compiled_flat_arms.relation_name) AS p
    ORDER BY jsonb_array_length(p.path), p.path::text
  LOOP
    prefixes := prefixes || jsonb_build_object(pl.path::text,
      to_jsonb(pl.rels));
    s := fga._compiled_place(store_id, model_id, target, pl.path,
      pl.place_type, pl.rels, pl.opaque, prefixes, ctx);
    objs := objs || s.objs;
    subs := subs || s.subs;
    arms := arms || s.check_arms;
    bools := bools || s.check_bools;
    errs := errs || s.check_errs;
  END LOOP;
  check_expr := fga._compiled_check_expr(bools, arms, errs);
END;
$$;

-- The contextual-tuple statements of a flattened relation, one per
-- kind, for fga.compiled_contextual.
CREATE OR REPLACE FUNCTION fga._compiled_ctx_stmts(
  store_id uuid, model_id uuid, target text,
  type_name text, relation_name text
)
RETURNS TABLE (kind text, stmt text)
LANGUAGE sql
STABLE PARALLEL SAFE
SET search_path = fga, pg_temp
AS $$
  SELECT v.kind, v.stmt
  FROM fga._compiled_flat_arms(store_id, model_id, target, type_name,
         relation_name, true) AS a
  CROSS JOIN LATERAL (VALUES
    ('objects', fga._compiled_ctx_stmt(store_id, model_id, 'YF100',
      'z.x', format(' CROSS JOIN LATERAL (%s) AS z(x)',
        array_to_string(a.objs, E'\nUNION\n')))),
    ('subjects', fga._compiled_ctx_stmt(store_id, model_id, 'YF100',
      'z.x', format(' CROSS JOIN LATERAL (%s) AS z(x)',
        array_to_string(a.subs, E'\nUNION\n')))),
    ('check', fga._compiled_ctx_stmt(store_id, model_id, 'YF127',
      a.check_expr, NULL))) AS v(kind, stmt);
$$;

-- The flattened emitter, which also serves the conditioned
-- strategy: one body over every place the relation reaches
-- (_compiled_places), with one dedup over the whole set, calling no
-- other relation's function but a set operation's. Only relations
-- the plan marked flattened or conditioned get here: no cycle,
-- bounded depth, and only their own direct grants carry conditions
-- — so the only errors a body can raise are its own condition
-- errors, which the arms and _compiled_assemble scope like the
-- generic resolver does.
--
-- Each kind is the arms over fga.tuple, run by a call without
-- contextual tuples (the test folds away when the call passes the
-- default), and for a call with some the dynamic statement over
-- both sources that _compiled_generate registers
-- (_compiled_ctx_stmts). A check is not inlined (its EXISTS runs as
-- its own statement), so its arms share one EXISTS: every subplan
-- of a plan starts on every call, run or not.
CREATE OR REPLACE FUNCTION fga._compiled_emit_flattened(
  store_id uuid, model_id uuid, target text,
  type_name text, relation_name text,
  OUT objects_body text, OUT subjects_body text, OUT check_body text
)
LANGUAGE plpgsql
STABLE PARALLEL SAFE
SET search_path = fga, pg_temp
AS $$
DECLARE
  live constant text := fga._compiled_no_ctuples_sql();
  args constant text := 'p_subject_type, p_subject_id, '
    'p_subject_relation, p_any_subject, p_context, '
    'p_contextual_tuples';
  key constant text := format('%L::pg_catalog.uuid, '
    '%L::pg_catalog.uuid, %L, %L', store_id, model_id, type_name,
    relation_name);
  f record := fga._compiled_flat_arms(store_id, model_id, target,
    type_name, relation_name, false);
  b record;
BEGIN
  b := fga._compiled_assemble(store_id, model_id,
    ARRAY(SELECT format('SELECT a.x FROM (%s) AS a(x) WHERE %s', a, live)
          FROM unnest(f.objs) WITH ORDINALITY AS u(a, i) ORDER BY i)
    || format('SELECT x FROM fga._compiled_ctx_set(%s, ''objects'', '
      'NULL, %s) AS x WHERE NOT %s', key, args, live),
    ARRAY(SELECT format('SELECT a.x FROM (%s) AS a(x) WHERE %s', a, live)
          FROM unnest(f.subs) WITH ORDINALITY AS u(a, i) ORDER BY i)
    || format('SELECT x FROM fga._compiled_ctx_set(%s, ''subjects'', '
      'p_object, p_subject_type, NULL, p_subject_relation, false, '
      'p_context, p_contextual_tuples) AS x WHERE NOT %s', key, live),
    ARRAY[format(E'CASE WHEN %s THEN %s\n  ELSE fga._compiled_ctx_bool('
      '%s, p_object, %s) END', live, f.check_expr, key, args)],
    '{}');
  objects_body := b.objects_body;
  subjects_body := b.subjects_body;
  check_body := b.check_body;
END;
$$;

-- One node of a set-operation rewrite: its objects, its check, and
-- its subjects as list_users computes them before any wildcard is
-- expanded — candidates (the concrete subjects of its grants) and
-- wild (whether a wildcard grant holds for the whole node). Unions
-- are UNION / OR; intersection is INTERSECT / AND and exclusion
-- EXCEPT / AND NOT of the operands' objects and checks. For
-- subjects, intersection keeps every operand's candidates and a
-- wildcard only when all operands grant one, and exclusion keeps
-- the base's candidates and its wildcard unless the subtract side
-- grants one too: the candidates then hold every subject the
-- relation grants, and the emitter filters them by its check. A
-- computed operand (the same object, another relation) is expanded
-- in place for subjects, as list_users expands it, so a wildcard it
-- grants joins wild instead of needing a subject source; wtypes
-- names the subject types such wildcards can be of. sid and anys
-- are the subject the checks ask about; depth names the aliases so
-- nested set operations never shadow each other.
CREATE OR REPLACE FUNCTION fga._compiled_setop_node(
  store_id uuid, model_id uuid, target text,
  type_name text, relation_name text, node jsonb,
  sid text, anys text, depth integer,
  OUT obj text, OUT sub text, OUT wild text, OUT chk text,
  OUT wtypes text[]
)
LANGUAGE plpgsql
STABLE PARALLEL SAFE
SET search_path = fga, pg_temp
AS $$
DECLARE
  mid constant uuid := model_id;
  q constant text := 'q' || depth;
  op text;
  o text[] := '{}';
  s text[] := '{}';
  w text[] := '{}';
  c text[] := '{}';
  k record;
  l record;
  me record;
  rw jsonb;
BEGIN
  wtypes := '{}';
  op := CASE WHEN node ? 'union' THEN 'UNION'
             WHEN node ? 'intersection' THEN 'INTERSECT'
             WHEN node ? 'difference' THEN 'EXCEPT' END;
  IF op IS NULL THEN
    l := fga._compiled_leaf(store_id, model_id, target, type_name,
      relation_name, node, sid, anys);
    obj := coalesce((SELECT string_agg(format(
        'SELECT a.x FROM (%s) AS a(x)', a), E'\nUNION\n' ORDER BY i)
      FROM unnest(l.objs) WITH ORDINALITY AS u(a, i)),
      'SELECT NULL::pg_catalog.uuid WHERE false');
    sub := coalesce((SELECT string_agg(format(
        'SELECT a.x FROM (%s) AS a(x)', a), E'\nUNION\n' ORDER BY i)
      FROM unnest(l.subs) WITH ORDINALITY AS u(a, i)),
      'SELECT NULL::pg_catalog.uuid WHERE false');
    wild := coalesce('(' || nullif(array_to_string(l.wilds, ' OR '),
      '') || ')', 'false');
    chk := coalesce('(' || nullif(array_to_string(l.checks
      || fga._compiled_ctx_exists(store_id, mid, l.ctx_checks, sid,
        anys), ' OR '),
      '') || ')', 'false');
    IF node ? 'this' THEN
      wtypes := ARRAY(
        SELECT DISTINCT tr.subject_type
        FROM fga.model_type_restriction tr
        WHERE tr.store = store_id AND tr.model_id = mid
          AND tr.type_name = _compiled_setop_node.type_name
          AND tr.relation_name = _compiled_setop_node.relation_name
          AND tr.is_wildcard);
    ELSIF node ? 'computed_userset' THEN
      SELECT mr.rewrite INTO rw FROM fga.model_relation mr
      WHERE mr.store = store_id AND mr.model_id = mid
        AND mr.type_name = _compiled_setop_node.type_name
        AND mr.relation_name
              = node -> 'computed_userset' ->> 'relation';
      k := fga._compiled_setop_node(store_id, mid, target,
        type_name, node -> 'computed_userset' ->> 'relation', rw,
        sid, anys, depth + 1);
      me := fga._compiled_self(type_name,
        node -> 'computed_userset' ->> 'relation');
      sub := format(E'SELECT %1$s.x FROM ((%2$s)\nUNION\n(%3$s)) '
        'AS %1$s(x)', q, me.sub, k.sub);
      wild := k.wild;
      wtypes := k.wtypes;
    END IF;
    RETURN;
  END IF;

  FOR k IN
    SELECT n.* FROM fga._rewrite_children(node) WITH ORDINALITY
      AS kid(child, i),
    LATERAL fga._compiled_setop_node(store_id, model_id, target,
      type_name, relation_name, kid.child, sid, anys, depth + 1) AS n
    ORDER BY kid.i
  LOOP
    o := o || k.obj;
    s := s || k.sub;
    w := w || k.wild;
    c := c || k.chk;
    wtypes := ARRAY(SELECT DISTINCT unnest(wtypes || k.wtypes));
  END LOOP;

  obj := format('SELECT %1$s.x FROM ((%2$s)) AS %1$s(x)', q,
    array_to_string(o, E')\n' || op || E'\n('));
  IF op = 'EXCEPT' THEN
    sub := s[1];
    wild := format('(%s AND NOT %s)', w[1], w[2]);
    chk := format('(%s AND NOT %s)', c[1], c[2]);
  ELSE
    sub := format('SELECT %1$s.x FROM ((%2$s)) AS %1$s(x)', q,
      array_to_string(s, E')\nUNION\n('));
    wild := '(' || array_to_string(w,
      CASE op WHEN 'UNION' THEN ' OR ' ELSE ' AND ' END) || ')';
    chk := '(' || array_to_string(c,
      CASE op WHEN 'UNION' THEN ' OR ' ELSE ' AND ' END) || ')';
  END IF;
END;
$$;

-- The set-operation emitter: the relation's rewrite as set
-- operations over its leaves, plus the subject itself. The plan
-- sends a relation here only when every relation it reaches can
-- neither raise nor cycle, and it has no condition of its own: a
-- set operation over such operands is exactly check's answer
-- (a cycled false on the subtract side, or an operand error a
-- sibling would swallow, would not be).
--
-- Subjects are the node's candidates, plus the registered subjects
-- of each wildcard type when the node's wildcard holds (an error
-- when no source is registered), kept only where the relation's
-- check allows them. The OFFSET 0 fence keeps that check from being
-- pushed below the wildcard's error, where it would hide it.
CREATE OR REPLACE FUNCTION fga._compiled_emit_setop(
  store_id uuid, model_id uuid, target text,
  type_name text, relation_name text,
  OUT objects_body text, OUT subjects_body text, OUT check_body text
)
LANGUAGE plpgsql
STABLE PARALLEL SAFE
SET search_path = fga, pg_temp
AS $$
DECLARE
  eq constant text := ' OPERATOR(pg_catalog.=) ';
  mid constant uuid := model_id;
  me record := fga._compiled_self(type_name, relation_name);
  rw jsonb;
  sources jsonb;
  src text[];
  n record;
  f record;
  b record;
  t text;
  cands text;
BEGIN
  SELECT mr.rewrite INTO rw FROM fga.model_relation mr
  WHERE mr.store = store_id AND mr.model_id = mid
    AND mr.type_name = _compiled_emit_setop.type_name
    AND mr.relation_name = _compiled_emit_setop.relation_name;
  SELECT cs.subject_sources INTO sources
  FROM fga.compiled_store cs WHERE cs.store = store_id;
  n := fga._compiled_setop_node(store_id, mid, target, type_name,
    relation_name, rw, 'p_subject_id', 'p_any_subject', 1);
  f := fga._compiled_setop_node(store_id, mid, target, type_name,
    relation_name, rw, 'q0.x', 'false', 1);

  cands := n.sub;
  FOR t IN SELECT x FROM unnest(n.wtypes) AS x ORDER BY 1 LOOP
    src := fga._compiled_parse_source(sources ->> t);
    IF src IS NOT NULL THEN
      cands := cands || format(E'\nUNION\nSELECT s.%I FROM %I.%I AS s '
        'WHERE p_subject_type%s%L AND p_subject_relation%s'''' AND %s',
        src[3], src[1], src[2], eq, t, eq, n.wild);
    ELSE
      cands := cands || format(E'\nUNION\nSELECT '
        'NULL::pg_catalog.uuid WHERE CASE WHEN p_subject_type%s%L '
        'AND p_subject_relation%s'''' AND %s THEN '
        'fga._compiled_no_source(%L, ''wildcard'') ELSE false END',
        eq, t, eq, n.wild, t);
    END IF;
  END LOOP;

  b := fga._compiled_assemble(store_id, mid,
    ARRAY[me.obj, n.obj],
    ARRAY[me.sub, format('SELECT q0.x FROM (SELECT c.x FROM (%s) '
      'AS c(x) OFFSET 0) AS q0(x) WHERE q0.x IS NOT NULL AND %s',
      cands, f.chk)],
    ARRAY[me.chk, n.chk], '{}');
  objects_body := b.objects_body;
  subjects_body := b.subjects_body;
  check_body := b.check_body;
END;
$$;

-- The qualified name of another relation's generated function.
CREATE OR REPLACE FUNCTION fga._compiled_ref(
  target text, type_name text, relation_name text, kind text
)
RETURNS text
LANGUAGE sql
IMMUTABLE PARALLEL SAFE
SET search_path = fga, pg_temp
AS $$
  SELECT format('%I.%I', target,
    fga._compiled_name(type_name, relation_name, kind));
$$;

-- The recursive emitter: a walk over the relation's reach in the
-- tuple graph, for relations on a cycle of the relation graph (same-
-- type parent chains, nested groups, a#m -> b#m -> a#m), relations
-- reaching one, and chains deep enough to meet check's depth limit.
-- One WITH RECURSIVE body per kind covers the whole sub-graph the
-- relation reaches; its edges are VALUES lists read from the model,
-- so the body calls no other generated function. That is on
-- purpose: __check must count every dispatch from its own root, and
-- a callee's __check would start counting again at zero.
--
-- The walk's nodes are (type, object, relation); UNION deduplicates
-- them, so cyclic data ends the walk.
--   __objects walks down from the subject, like list_objects, and
--        charges no depth.
--   __check walks up from the object, recording each node's dispatch
--        count d (computed usersets cost nothing). A grant at d <= 25
--        is check's true: the shortest path to it is simple, and
--        check's search follows every simple path of up to 25
--        dispatches. Otherwise check answers false or raises YF102,
--        and it raises only from a simple path of 25 dispatches whose
--        last node has a row to dispatch, which needs both a walk row
--        at d = 26 and 26 distinct nodes (the root and 25 distinct
--        dispatch targets). Without both, false is exact; with both,
--        the generic resolver decides, so the error is check's own.
--   __subjects walks up like __check. list_users refuses as soon as
--        it enters a node 25 dispatches away, whatever it found
--        elsewhere: a walk row at d = 25 and 26 distinct nodes hand
--        the call to the generic path, anything less is exact here.
CREATE OR REPLACE FUNCTION fga._compiled_emit_recursive(
  store_id uuid, model_id uuid, target text,
  type_name text, relation_name text,
  OUT objects_body text, OUT subjects_body text, OUT check_body text
)
LANGUAGE plpgsql
STABLE PARALLEL SAFE
SET search_path = fga, pg_temp
AS $$
DECLARE
  mid constant uuid := model_id;
  root_type constant text := type_name;
  root_rel constant text := relation_name;
  eq constant text := ' OPERATOR(pg_catalog.=) ';
  ne constant text := ' OPERATOR(pg_catalog.<>) ';
  store_lit constant text := format('%L::pg_catalog.uuid', store_id);
  nil constant text :=
    '''00000000-0000-0000-0000-000000000000''::pg_catalog.uuid';
  uncond constant text := '(g.condition_name IS NULL OR '
    'g.condition_name OPERATOR(pg_catalog.=) '''')';
  live constant text := fga._compiled_no_ctuples_sql();
  sub text[];
  direct_v text;
  userset_v text;
  computed_v text;
  ttu_v text;
  down text[] := '{}';
  seeds text[] := '{}';
  grant_at text;
  walk_check text;
  walk_subjects text;
  risky text;
  subs text[] := '{}';
  sources jsonb;
  src text[];
  d record;
  r record;
BEGIN
  SELECT cs.subject_sources INTO sources
  FROM fga.compiled_store cs WHERE cs.store = store_id;
  d := fga._compiled_emit_delegated(
    store_id, model_id, root_type, root_rel);

  -- The sub-graph: every relation the root reaches, and itself.
  WITH RECURSIVE e AS MATERIALIZED (
    SELECT * FROM fga._compiled_edges(store_id, mid)
  ), s(t, r) AS (
    SELECT root_type, root_rel
    UNION
    SELECT e.to_type, e.to_relation
    FROM s JOIN e ON e.type_name = s.t AND e.relation_name = s.r
  )
  SELECT array_agg(s.t || '#' || s.r) INTO sub FROM s;

  -- Grants that end a path: direct restrictions without a relation.
  SELECT string_agg(format('(%L::pg_catalog.text, %L::pg_catalog.text, '
      '%L::pg_catalog.text, %L::pg_catalog.bool)',
      x.t, x.r, x.st, x.wild), ', ' ORDER BY x.t, x.r, x.st, x.wild)
  INTO direct_v
  FROM (
    SELECT DISTINCT tr.type_name AS t, tr.relation_name AS r,
           tr.subject_type AS st, tr.is_wildcard AS wild
    FROM fga.model_type_restriction tr
    WHERE tr.store = store_id AND tr.model_id = mid
      AND tr.type_name || '#' || tr.relation_name = ANY (sub)
      AND tr.subject_relation = ''
      AND EXISTS (
        SELECT FROM fga.model_relation mr,
             fga._rewrite_nodes(mr.rewrite) AS n
        WHERE mr.store = store_id AND mr.model_id = mid
          AND mr.type_name = tr.type_name
          AND mr.relation_name = tr.relation_name AND n ? 'this')
  ) AS x;

  -- Userset restrictions: a dispatch to the subject's relation.
  SELECT string_agg(format('(%L::pg_catalog.text, %L::pg_catalog.text, '
      '%L::pg_catalog.text, %L::pg_catalog.text)',
      x.t, x.r, x.st, x.sr), ', ' ORDER BY x.t, x.r, x.st, x.sr)
  INTO userset_v
  FROM (
    SELECT DISTINCT tr.type_name AS t, tr.relation_name AS r,
           tr.subject_type AS st, tr.subject_relation AS sr
    FROM fga.model_type_restriction tr
    WHERE tr.store = store_id AND tr.model_id = mid
      AND tr.type_name || '#' || tr.relation_name = ANY (sub)
      AND tr.subject_relation <> ''
      AND EXISTS (
        SELECT FROM fga.model_relation mr,
             fga._rewrite_nodes(mr.rewrite) AS n
        WHERE mr.store = store_id AND mr.model_id = mid
          AND mr.type_name = tr.type_name
          AND mr.relation_name = tr.relation_name AND n ? 'this')
  ) AS x;

  -- Computed usersets: the same object, another relation.
  SELECT string_agg(format('(%L::pg_catalog.text, %L::pg_catalog.text, '
      '%L::pg_catalog.text)', x.t, x.r, x.r2), ', '
      ORDER BY x.t, x.r, x.r2)
  INTO computed_v
  FROM (
    SELECT DISTINCT mr.type_name AS t, mr.relation_name AS r,
           n -> 'computed_userset' ->> 'relation' AS r2
    FROM fga.model_relation mr, fga._rewrite_nodes(mr.rewrite) AS n
    WHERE mr.store = store_id AND mr.model_id = mid
      AND mr.type_name || '#' || mr.relation_name = ANY (sub)
      AND n ? 'computed_userset'
  ) AS x;

  -- Tuple-to-userset: each parent type the tupleset admits that
  -- defines the computed relation (a parent type without it adds
  -- nothing, as in check).
  SELECT string_agg(format('(%L::pg_catalog.text, %L::pg_catalog.text, '
      '%L::pg_catalog.text, %L::pg_catalog.text, %L::pg_catalog.text)',
      x.t, x.r, x.ts, x.pt, x.cr), ', '
      ORDER BY x.t, x.r, x.ts, x.pt, x.cr)
  INTO ttu_v
  FROM (
    SELECT DISTINCT mr.type_name AS t, mr.relation_name AS r,
      n -> 'tuple_to_userset' -> 'tupleset' ->> 'relation' AS ts,
      tr.subject_type AS pt,
      n -> 'tuple_to_userset' -> 'computed_userset' ->> 'relation'
        AS cr
    FROM fga.model_relation mr
    CROSS JOIN LATERAL fga._rewrite_nodes(mr.rewrite) AS n
    JOIN fga.model_type_restriction tr
      ON tr.store = store_id AND tr.model_id = mid
     AND tr.type_name = mr.type_name
     AND tr.relation_name
           = n -> 'tuple_to_userset' -> 'tupleset' ->> 'relation'
    WHERE mr.store = store_id AND mr.model_id = mid
      AND mr.type_name || '#' || mr.relation_name = ANY (sub)
      AND n ? 'tuple_to_userset'
      AND tr.subject_relation = '' AND NOT tr.is_wildcard
      AND EXISTS (
        SELECT FROM fga.model_relation p
        WHERE p.store = store_id AND p.model_id = mid
          AND p.type_name = tr.subject_type
          AND p.relation_name = n -> 'tuple_to_userset'
                -> 'computed_userset' ->> 'relation')
  ) AS x;

  -- __objects: down from the subject. Seeds are the rows granting
  -- it directly (a wildcard row grants every subject of its type)
  -- and, for a userset subject, the subject itself.
  IF direct_v IS NOT NULL THEN
    seeds := seeds || format(
      'SELECT a.t, g.object_id, a.r FROM (VALUES %2$s) AS a(t, r, st, '
      'wild) JOIN fga.tuple AS g ON g.store%1$s%3$s AND '
      'g.subject_type%1$sa.st AND g.subject_id%1$sCASE WHEN a.wild '
      'THEN %4$s ELSE p_subject_id END AND g.subject_relation%1$s'''' '
      'AND g.relation%1$sa.r AND g.object_type%1$sa.t '
      'WHERE a.st%1$sp_subject_type AND p_subject_relation%1$s'''' '
      'AND (a.wild OR NOT p_any_subject) AND %5$s',
      eq, direct_v, store_lit, nil, uncond);
  END IF;
  seeds := seeds || format(
    'SELECT p_subject_type, p_subject_id, p_subject_relation '
    'WHERE p_subject_relation%s'''' AND NOT p_any_subject', ne);
  IF computed_v IS NOT NULL THEN
    down := down || format(
      'SELECT c.t, w.o, c.r FROM (VALUES %2$s) AS c(t, r, r2) '
      'WHERE c.t%1$sw.t AND c.r2%1$sw.r', eq, computed_v);
  END IF;
  IF userset_v IS NOT NULL THEN
    down := down || format(
      'SELECT u.t, g.object_id, u.r FROM (VALUES %2$s) AS u(t, r, st, '
      'sr) JOIN fga.tuple AS g ON g.store%1$s%3$s AND '
      'g.subject_type%1$sw.t AND g.subject_id%1$sw.o AND '
      'g.subject_relation%1$sw.r AND g.relation%1$su.r AND '
      'g.object_type%1$su.t WHERE u.st%1$sw.t AND u.sr%1$sw.r AND %4$s',
      eq, userset_v, store_lit, uncond);
  END IF;
  IF ttu_v IS NOT NULL THEN
    down := down || format(
      'SELECT p.t, g.object_id, p.r FROM (VALUES %2$s) AS p(t, r, ts, '
      'pt, cr) JOIN fga.tuple AS g ON g.store%1$s%3$s AND '
      'g.subject_type%1$sw.t AND g.subject_id%1$sw.o AND '
      'g.subject_relation%1$s'''' AND g.relation%1$sp.ts AND '
      'g.object_type%1$sp.t WHERE p.pt%1$sw.t AND p.cr%1$sw.r AND %4$s',
      eq, ttu_v, store_lit, uncond);
  END IF;
  objects_body := format(
    E'WITH RECURSIVE w(t, o, r) AS (\n%s\nUNION\n'
    || 'SELECT n.t, n.o, n.r FROM w CROSS JOIN LATERAL (%s) AS n(t, o, r)'
    || E'\n)\nSELECT NULL::pg_catalog.uuid WHERE fga._compiled_sid('
    || 'p_subject_id, p_any_subject, p_subject_relation) IS NULL'
    || E'\nUNION\n%s WHERE NOT %s'
    || E'\nUNION\nSELECT w.o FROM w WHERE %s AND w.t%s%L AND w.r%s%L',
    array_to_string(seeds, E'\nUNION\n'),
    array_to_string(down, ' UNION ALL '),
    d.objects_body, live, live, eq, root_type, eq, root_rel);

  -- __check and __subjects: up from the object, counting dispatches
  -- up to a limit one past the counterpart's boundary.
  walk_check := fga._compiled_walk_up(store_id, root_type, root_rel,
    computed_v, userset_v, ttu_v, 26);
  walk_subjects := fga._compiled_walk_up(store_id, root_type,
    root_rel, computed_v, userset_v, ttu_v, 25);

  -- A grant at node w: w is the subject itself, or a row of w names
  -- the subject (a wildcard row any subject of its type).
  grant_at := format('(w.t%1$sp_subject_type AND w.o%1$sp_subject_id '
    'AND w.r%1$sp_subject_relation AND NOT p_any_subject)', eq);
  IF direct_v IS NOT NULL THEN
    grant_at := grant_at || format(
      ' OR EXISTS (SELECT FROM (VALUES %2$s) AS a(t, r, st, wild) '
      'JOIN fga.tuple AS g ON g.store%1$s%3$s AND g.object_type%1$sw.t '
      'AND g.object_id%1$sw.o AND g.relation%1$sw.r AND '
      'g.subject_type%1$sa.st AND g.subject_id%1$sCASE WHEN a.wild '
      'THEN %4$s ELSE p_subject_id END AND g.subject_relation%1$s'''' '
      'WHERE a.t%1$sw.t AND a.r%1$sw.r AND a.st%1$sp_subject_type AND '
      'p_subject_relation%1$s'''' AND (a.wild OR NOT p_any_subject) '
      'AND %5$s)', eq, direct_v, store_lit, nil, uncond);
  END IF;
  IF userset_v IS NOT NULL THEN
    grant_at := grant_at || format(
      ' OR EXISTS (SELECT FROM (VALUES %2$s) AS u(t, r, st, sr) '
      'JOIN fga.tuple AS g ON g.store%1$s%3$s AND g.object_type%1$sw.t '
      'AND g.object_id%1$sw.o AND g.relation%1$sw.r AND '
      'g.subject_type%1$su.st AND g.subject_id%1$sp_subject_id AND '
      'g.subject_relation%1$su.sr WHERE u.t%1$sw.t AND u.r%1$sw.r AND '
      'u.st%1$sp_subject_type AND u.sr%1$sp_subject_relation AND NOT '
      'p_any_subject AND %4$s)', eq, userset_v, store_lit, uncond);
  END IF;

  risky := '(SELECT pg_catalog.count(*) FROM (SELECT DISTINCT w.t, '
    'w.o, w.r FROM w) AS n) OPERATOR(pg_catalog.>=) 26';
  check_body := fga._compiled_no_inline() || format(
    E'%s\nSELECT fga._compiled_sid(p_subject_id, p_any_subject, '
    || 'p_subject_relation) IS NOT NULL AND fga._compiled_oid(p_object) '
    'IS NOT NULL AND CASE WHEN NOT %s THEN (%s) '
    'WHEN EXISTS (SELECT FROM w WHERE w.d OPERATOR(pg_catalog.<=) 25 '
    'AND (%s)) THEN true '
    'WHEN EXISTS (SELECT FROM w WHERE w.d OPERATOR(pg_catalog.>=) 26) '
    'AND %s THEN (%s) ELSE false END',
    walk_check, live, substr(d.check_body, length('SELECT ') + 1),
    grant_at, risky, substr(d.check_body, length('SELECT ') + 1));

  -- __subjects: the nodes of the asked userset type themselves,
  -- plain rows of the asked type, and wildcard rows expanded over
  -- the registered subject source.
  subs := subs || format('SELECT w.o FROM w WHERE w.t%1$sp_subject_type '
    'AND w.r%1$sp_subject_relation', eq);
  IF direct_v IS NOT NULL THEN
    subs := subs || format(
      'SELECT g.subject_id FROM w JOIN (VALUES %2$s) AS a(t, r, st, '
      'wild) ON a.t%1$sw.t AND a.r%1$sw.r JOIN fga.tuple AS g ON '
      'g.store%1$s%3$s AND g.object_type%1$sw.t AND g.object_id%1$sw.o '
      'AND g.relation%1$sw.r AND g.subject_type%1$sa.st AND '
      'g.subject_relation%1$s'''' WHERE NOT a.wild AND '
      'a.st%1$sp_subject_type AND p_subject_relation%1$s'''' AND '
      'g.subject_id%4$s%5$s AND %6$s',
      eq, direct_v, store_lit, ne, nil, uncond);
  END IF;
  FOR r IN
    SELECT DISTINCT tr.subject_type AS st
    FROM fga.model_type_restriction tr
    WHERE tr.store = store_id AND tr.model_id = mid
      AND tr.type_name || '#' || tr.relation_name = ANY (sub)
      AND tr.is_wildcard
    ORDER BY 1
  LOOP
    src := fga._compiled_parse_source(sources ->> r.st);
    IF src IS NOT NULL THEN
      subs := subs || format(
        'SELECT s.%2$I FROM %3$I.%4$I AS s WHERE '
        'p_subject_type%1$s%5$L AND p_subject_relation%1$s'''' AND '
        'EXISTS (SELECT FROM w JOIN (VALUES %6$s) AS a(t, r, st, wild) '
        'ON a.t%1$sw.t AND a.r%1$sw.r JOIN fga.tuple AS g ON '
        'g.store%1$s%7$s AND g.object_type%1$sw.t AND '
        'g.object_id%1$sw.o AND g.relation%1$sw.r AND '
        'g.subject_type%1$sa.st AND g.subject_id%1$s%8$s AND '
        'g.subject_relation%1$s'''' WHERE a.wild AND a.st%1$s%5$L AND '
        '%9$s)', eq, src[3], src[1], src[2], r.st, direct_v,
        store_lit, nil, uncond);
    ELSE
      subs := subs || format(
        'SELECT g.subject_id FROM w JOIN (VALUES %2$s) AS a(t, r, st, '
        'wild) ON a.t%1$sw.t AND a.r%1$sw.r JOIN fga.tuple AS g ON '
        'g.store%1$s%3$s AND g.object_type%1$sw.t AND '
        'g.object_id%1$sw.o AND g.relation%1$sw.r AND '
        'g.subject_type%1$sa.st AND g.subject_id%1$s%4$s AND '
        'g.subject_relation%1$s'''' WHERE a.wild AND a.st%1$s%5$L AND '
        'p_subject_type%1$s%5$L AND p_subject_relation%1$s'''' AND %6$s '
        'AND fga._compiled_no_source(%5$L, g.ulid)',
        eq, direct_v, store_lit, nil, r.st, uncond);
    END IF;
  END LOOP;

  risky := format('(EXISTS (SELECT FROM w WHERE w.d '
    'OPERATOR(pg_catalog.>=) 25) AND %s)', risky);
  subjects_body := format(
    E'%s\nSELECT NULL::pg_catalog.uuid WHERE '
    || 'fga._compiled_oid(p_object) IS NULL'
    || E'\nUNION\n%s WHERE NOT %s OR %s', walk_subjects,
    d.subjects_body, live, risky)
    || (SELECT string_agg(format(
         E'\nUNION\nSELECT a.x FROM (%s) AS a(x) WHERE %s AND NOT %s',
         a, live, risky), '' ORDER BY i)
        FROM unnest(subs) WITH ORDINALITY AS u(a, i));
END;
$$;

-- The upward walk shared by __check and __subjects: a WITH RECURSIVE
-- named w(t, o, r, d) from the generated function's p_object, where
-- d counts dispatches; a node at the limit dispatches no further,
-- which ends the walk on cyclic data too.
CREATE OR REPLACE FUNCTION fga._compiled_walk_up(
  store_id uuid, root_type text, root_rel text,
  computed_v text, userset_v text, ttu_v text, depth_limit integer
)
RETURNS text
LANGUAGE plpgsql
IMMUTABLE PARALLEL SAFE
SET search_path = fga, pg_temp
AS $$
DECLARE
  eq constant text := ' OPERATOR(pg_catalog.=) ';
  store_lit constant text := format('%L::pg_catalog.uuid', store_id);
  next_d constant text := 'w.d OPERATOR(pg_catalog.+) 1';
  below constant text := format('w.d OPERATOR(pg_catalog.<) %s',
    depth_limit);
  uncond constant text := '(g.condition_name IS NULL OR '
    'g.condition_name OPERATOR(pg_catalog.=) '''')';
  up text[] := '{}';
BEGIN
  IF computed_v IS NOT NULL THEN
    up := up || format(
      'SELECT w.t, w.o, c.r2, w.d FROM (VALUES %2$s) AS c(t, r, r2) '
      'WHERE c.t%1$sw.t AND c.r%1$sw.r', eq, computed_v);
  END IF;
  IF userset_v IS NOT NULL THEN
    up := up || format(
      'SELECT g.subject_type, g.subject_id, g.subject_relation, %5$s '
      'FROM (VALUES %2$s) AS u(t, r, st, sr) JOIN fga.tuple AS g ON '
      'g.store%1$s%3$s AND g.object_type%1$sw.t AND g.object_id%1$sw.o '
      'AND g.relation%1$sw.r AND g.subject_type%1$su.st AND '
      'g.subject_relation%1$su.sr WHERE u.t%1$sw.t AND u.r%1$sw.r AND '
      '%6$s AND %4$s', eq, userset_v, store_lit, uncond, next_d, below);
  END IF;
  IF ttu_v IS NOT NULL THEN
    up := up || format(
      'SELECT p.pt, g.subject_id, p.cr, %5$s FROM (VALUES %2$s) AS '
      'p(t, r, ts, pt, cr) JOIN fga.tuple AS g ON g.store%1$s%3$s AND '
      'g.object_type%1$sw.t AND g.object_id%1$sw.o AND '
      'g.relation%1$sp.ts AND g.subject_type%1$sp.pt AND '
      'g.subject_relation%1$s'''' AND g.subject_id '
      'OPERATOR(pg_catalog.<>) '
      '''00000000-0000-0000-0000-000000000000''::pg_catalog.uuid '
      'WHERE p.t%1$sw.t AND p.r%1$sw.r AND %6$s AND %4$s',
      eq, ttu_v, store_lit, uncond, next_d, below);
  END IF;
  RETURN format(
    E'WITH RECURSIVE w(t, o, r, d) AS (\nSELECT %L::pg_catalog.text, '
    || E'p_object, %L::pg_catalog.text, 0\nUNION\n'
    'SELECT n.t, n.o, n.r, n.d FROM w CROSS JOIN LATERAL (%s) '
    || E'AS n(t, o, r, d)\n)',
    root_type, root_rel, array_to_string(up, ' UNION ALL '));
END;
$$;

-- The edges of a model's relation graph: a relation points at every
-- relation its rewrite can reach in one step — a computed userset
-- (same object, hop 0), a userset restriction or a tuple-to-userset
-- parent that defines the computed relation (another object, hop 1:
-- a dispatch, the only step that spends check's depth budget).
CREATE OR REPLACE FUNCTION fga._compiled_edges(
  store_id uuid, model_id uuid
)
RETURNS TABLE (type_name text, relation_name text, to_type text,
               to_relation text, hop integer)
LANGUAGE sql
STABLE PARALLEL SAFE
SET search_path = fga, pg_temp
AS $$
  WITH
  rel AS (
    SELECT r.type_name, r.relation_name, r.rewrite
    FROM fga.model_relation r
    WHERE r.store = store_id AND r.model_id = _compiled_edges.model_id
  ),
  node AS (
    SELECT rel.type_name, rel.relation_name, n
    FROM rel, fga._rewrite_nodes(rel.rewrite) AS n
  ),
  restriction AS (
    SELECT tr.* FROM fga.model_type_restriction tr
    WHERE tr.store = store_id
      AND tr.model_id = _compiled_edges.model_id
  )
  SELECT nd.type_name, nd.relation_name, nd.type_name AS to_type,
         nd.n -> 'computed_userset' ->> 'relation' AS to_relation,
         0 AS hop
  FROM node nd WHERE nd.n ? 'computed_userset'
  UNION ALL
  SELECT nd.type_name, nd.relation_name, tr.subject_type,
         nd.n -> 'tuple_to_userset' -> 'computed_userset'
           ->> 'relation', 1
  FROM node nd
  JOIN restriction tr
    ON tr.type_name = nd.type_name
   AND tr.relation_name
         = nd.n -> 'tuple_to_userset' -> 'tupleset' ->> 'relation'
  JOIN rel p
    ON p.type_name = tr.subject_type
   AND p.relation_name = nd.n -> 'tuple_to_userset'
         -> 'computed_userset' ->> 'relation'
  WHERE nd.n ? 'tuple_to_userset'
    AND tr.subject_relation = '' AND NOT tr.is_wildcard
  UNION ALL
  SELECT nd.type_name, nd.relation_name, tr.subject_type,
         tr.subject_relation, 1
  FROM node nd
  JOIN restriction tr
    ON tr.type_name = nd.type_name
   AND tr.relation_name = nd.relation_name
  WHERE nd.n ? 'this' AND tr.subject_relation <> '';
$$;

-- The strategy of every relation of a model, the reason a
-- relation is delegated, and the order to create functions in
-- (callees before callers).
--
-- Each relation's own rewrite decides first:
--   generic      only the generic resolver answers it (the reason
--                says why) — it, and everything reaching it,
--                delegates;
--   setop        intersection or exclusion;
--   conditioned  conditions on its own plain or wildcard grants;
--   otherwise    unions of direct grants, computed usersets and
--                tuple-to-usersets.
-- A plain relation flattens when it reaches no cycle, no conditioned
-- relation and no chain deep enough for check's depth limit. A
-- set operation or conditioned relation compiles under the same
-- three conditions, since it is exact only over operands that answer
-- plainly true or false: a cycled false on the subtract side, a
-- depth error or a condition error a sibling would swallow are not.
-- A relation on (or reaching) a cycle, or deep, compiles to the
-- recursive walk instead — when every relation it reaches is plain,
-- because the walk reads tuples itself and knows only plain
-- rewrites. Anything else delegates.
CREATE OR REPLACE FUNCTION fga._compiled_plan(
  store_id uuid, model_id uuid
)
RETURNS TABLE (type_name text, relation_name text, strategy text,
               reason text, ord integer)
LANGUAGE sql
STABLE PARALLEL SAFE
SET search_path = fga, pg_temp
AS $$
  WITH RECURSIVE
  rel AS (
    SELECT r.type_name, r.relation_name, r.rewrite, r.needs_check
    FROM fga.model_relation r
    WHERE r.store = store_id AND r.model_id = _compiled_plan.model_id
  ),
  node AS (
    SELECT rel.type_name, rel.relation_name, n
    FROM rel, fga._rewrite_nodes(rel.rewrite) AS n
  ),
  restriction AS (
    SELECT tr.* FROM fga.model_type_restriction tr
    WHERE tr.store = store_id AND tr.model_id = _compiled_plan.model_id
  ),
  edge AS (
    SELECT * FROM fga._compiled_edges(store_id, _compiled_plan.model_id)
  ),
  own AS (
    SELECT rel.type_name, rel.relation_name, CASE
      WHEN EXISTS (
        SELECT FROM node nd
        WHERE nd.type_name = rel.type_name
          AND nd.relation_name = rel.relation_name
          AND NOT (nd.n ?| ARRAY['this', 'union', 'intersection',
                                 'difference', 'computed_userset',
                                 'tuple_to_userset'])
      ) THEN 'unsupported rewrite'
      WHEN EXISTS (
        SELECT FROM node nd JOIN restriction tr
          ON tr.type_name = nd.type_name
         AND tr.relation_name
               = nd.n -> 'tuple_to_userset' -> 'tupleset' ->> 'relation'
        WHERE nd.type_name = rel.type_name
          AND nd.relation_name = rel.relation_name
          AND (tr.condition_name <> '' OR tr.is_wildcard
               OR tr.subject_relation <> '')
      ) THEN 'conditioned or indirect tupleset'
      WHEN cond.userset THEN 'conditioned userset grant'
      WHEN cond.direct AND rel.needs_check
      THEN 'conditioned grant in a set operation'
    END AS generic,
    CASE WHEN rel.needs_check THEN 'intersection or exclusion'
         WHEN cond.direct THEN 'conditioned grant' END AS kind
    FROM rel
    CROSS JOIN LATERAL (
      SELECT coalesce(bool_or(tr.subject_relation = ''), false)
               AS direct,
             coalesce(bool_or(tr.subject_relation <> ''), false)
               AS userset
      FROM node nd JOIN restriction tr
        ON tr.type_name = nd.type_name
       AND tr.relation_name = nd.relation_name
      WHERE nd.type_name = rel.type_name
        AND nd.relation_name = rel.relation_name
        AND nd.n ? 'this' AND tr.condition_name <> ''
    ) AS cond
  ),
  reach AS (
    SELECT e.type_name, e.relation_name, e.to_type, e.to_relation
    FROM edge e
    UNION
    SELECT x.type_name, x.relation_name, e.to_type, e.to_relation
    FROM reach x
    JOIN edge e
      ON e.type_name = x.to_type AND e.relation_name = x.to_relation
  ),
  -- Relations on a cycle of the relation graph.
  cyclic AS (
    SELECT x.type_name, x.relation_name FROM reach x
    WHERE x.to_type = x.type_name AND x.to_relation = x.relation_name
  ),
  -- Per relation: the first thing it is, or reaches, that only the
  -- generic resolver answers; the first set operation or conditioned
  -- relation it reaches (the recursive walk handles neither); the
  -- first conditioned relation it reaches (it may raise); and whether
  -- it is on, or reaches, a cycle.
  facts AS (
    SELECT o.type_name, o.relation_name, o.kind,
      coalesce(o.generic, (
        SELECT 'reaches ' || x.to_type || '#' || x.to_relation
               || ' (' || oo.generic || ')'
        FROM reach x JOIN own oo
          ON oo.type_name = x.to_type
         AND oo.relation_name = x.to_relation
        WHERE x.type_name = o.type_name
          AND x.relation_name = o.relation_name
          AND oo.generic IS NOT NULL
        ORDER BY 1 LIMIT 1)) AS generic,
      (SELECT 'reaches ' || x.to_type || '#' || x.to_relation
              || ' (' || oo.kind || ')'
       FROM reach x JOIN own oo
         ON oo.type_name = x.to_type
        AND oo.relation_name = x.to_relation
       WHERE x.type_name = o.type_name
         AND x.relation_name = o.relation_name
         AND oo.kind IS NOT NULL
       ORDER BY 1 LIMIT 1) AS reaches_kind,
      (SELECT 'reaches ' || x.to_type || '#' || x.to_relation
              || ' (' || oo.kind || ')'
       FROM reach x JOIN own oo
         ON oo.type_name = x.to_type
        AND oo.relation_name = x.to_relation
       WHERE x.type_name = o.type_name
         AND x.relation_name = o.relation_name
         AND oo.kind = 'conditioned grant'
       ORDER BY 1 LIMIT 1) AS reaches_cond,
      EXISTS (
        SELECT FROM cyclic c
        WHERE (c.type_name, c.relation_name)
                = (o.type_name, o.relation_name)
           OR EXISTS (
             SELECT FROM reach x
             WHERE x.type_name = o.type_name
               AND x.relation_name = o.relation_name
               AND x.to_type = c.type_name
               AND x.to_relation = c.relation_name)) AS cycles
    FROM own o
  ),
  -- Paths from every relation reaching no cycle, so the walk ends.
  -- hops is the dispatch depth, len the call depth.
  walk AS (
    SELECT f.type_name AS root_type, f.relation_name AS root_relation,
           f.type_name, f.relation_name, 0 AS hops, 0 AS len
    FROM facts f WHERE NOT f.cycles
    UNION
    SELECT w.root_type, w.root_relation, e.to_type, e.to_relation,
           w.hops + e.hop, w.len + 1
    FROM walk w
    JOIN edge e
      ON e.type_name = w.type_name
     AND e.relation_name = w.relation_name
    WHERE w.hops < 25
  ),
  depth AS (
    SELECT w.root_type, w.root_relation,
           max(w.hops) AS hops, max(w.len) AS len
    FROM walk w GROUP BY 1, 2
  ),
  verdict AS (
    SELECT f.type_name, f.relation_name, d.len, CASE
      WHEN f.generic IS NOT NULL THEN f.generic
      WHEN NOT f.cycles AND d.hops < 24 THEN f.reaches_cond
      WHEN f.kind IS NOT NULL THEN f.kind || CASE WHEN f.cycles
        THEN ' on or reaching a cycle of the relation graph'
        ELSE ' with a dispatch depth that may reach the resolution '
             'limit' END
      ELSE f.reaches_kind
    END AS reason,
    f.kind, NOT f.cycles AND d.hops < 24 AS flat
    FROM facts f
    LEFT JOIN depth d
      ON d.root_type = f.type_name AND d.root_relation = f.relation_name
  )
  SELECT v.type_name, v.relation_name,
    CASE WHEN v.reason IS NOT NULL THEN 'delegated'
         WHEN NOT v.flat THEN 'recursive'
         WHEN v.kind = 'intersection or exclusion' THEN 'setop'
         WHEN v.kind = 'conditioned grant' THEN 'conditioned'
         ELSE 'flattened' END,
    v.reason,
    CASE WHEN v.reason IS NULL AND v.flat THEN 1 + v.len ELSE 0 END
  FROM verdict v;
$$;

-- The note a relation's registry reason carries when its
-- __subjects may meet a wildcard grant of a type the store has
-- registered no subject source for: such a call raises rather than
-- return a partial list, and the registry says so from the model
-- write on. NULL when every wildcard the relation can reach — on
-- itself, through computed usersets, tuple-to-usersets or userset
-- grants — has a source.
CREATE OR REPLACE FUNCTION fga._compiled_source_note(
  store_id uuid, model_id uuid, type_name text, relation_name text
)
RETURNS text
LANGUAGE sql
STABLE PARALLEL SAFE
SET search_path = fga, pg_temp
AS $$
  WITH RECURSIVE
  node AS (
    SELECT r.type_name, r.relation_name, n
    FROM fga.model_relation r, fga._rewrite_nodes(r.rewrite) AS n
    WHERE r.store = store_id
      AND r.model_id = _compiled_source_note.model_id
  ),
  restriction AS (
    SELECT tr.* FROM fga.model_type_restriction tr
    WHERE tr.store = store_id
      AND tr.model_id = _compiled_source_note.model_id
  ),
  edge AS (
    SELECT nd.type_name, nd.relation_name, nd.type_name AS to_type,
           nd.n -> 'computed_userset' ->> 'relation' AS to_relation
    FROM node nd WHERE nd.n ? 'computed_userset'
    UNION ALL
    SELECT nd.type_name, nd.relation_name, tr.subject_type,
           nd.n -> 'tuple_to_userset' -> 'computed_userset'
             ->> 'relation'
    FROM node nd
    JOIN restriction tr
      ON tr.type_name = nd.type_name
     AND tr.relation_name
           = nd.n -> 'tuple_to_userset' -> 'tupleset' ->> 'relation'
    WHERE nd.n ? 'tuple_to_userset'
      AND tr.subject_relation = '' AND NOT tr.is_wildcard
    UNION ALL
    SELECT nd.type_name, nd.relation_name, tr.subject_type,
           tr.subject_relation
    FROM node nd
    JOIN restriction tr
      ON tr.type_name = nd.type_name
     AND tr.relation_name = nd.relation_name
    WHERE nd.n ? 'this' AND tr.subject_relation <> ''
  ),
  reach AS (
    SELECT _compiled_source_note.type_name,
           _compiled_source_note.relation_name
    UNION
    SELECT e.to_type, e.to_relation
    FROM reach x
    JOIN edge e
      ON e.type_name = x.type_name
     AND e.relation_name = x.relation_name
  )
  SELECT '__subjects: no subject source registered for wildcard '
    || 'type ' || string_agg(DISTINCT tr.subject_type, ', '
                             ORDER BY tr.subject_type)
  FROM reach x
  JOIN restriction tr
    ON tr.type_name = x.type_name
   AND tr.relation_name = x.relation_name
  WHERE tr.is_wildcard
    AND EXISTS (
      SELECT FROM node nd
      WHERE nd.type_name = x.type_name
        AND nd.relation_name = x.relation_name AND nd.n ? 'this')
    AND NOT EXISTS (
      SELECT FROM fga.compiled_store cs
      WHERE cs.store = store_id
        AND cs.subject_sources ? tr.subject_type);
$$;

-- Every function of a model: names, signatures and definitions,
-- each body from its relation's strategy emitter.
CREATE OR REPLACE FUNCTION fga._compiled_functions(
  store_id uuid, model_id uuid, target text
)
RETURNS TABLE (type_name text, relation_name text, kind text,
               name text, sig text, ddl text, strategy text,
               reason text, ord integer)
LANGUAGE sql
STABLE PARALLEL SAFE
SET search_path = fga, pg_temp
AS $$
  SELECT p.type_name, p.relation_name, k.kind, n.name,
    format('%I.%I(%s)', target, n.name,
           fga._compiled_arg_types(k.kind)),
    fga._compiled_ddl(target, n.name, k.kind, CASE k.kind
      WHEN 'objects' THEN b.objects_body
      WHEN 'subjects' THEN b.subjects_body
      ELSE b.check_body END),
    p.strategy,
    nullif(concat_ws('; ', p.reason, fga._compiled_source_note(
      store_id, model_id, p.type_name, p.relation_name)), ''),
    p.ord
  FROM fga._compiled_plan(store_id, model_id) AS p
  CROSS JOIN LATERAL (
    SELECT * FROM fga._compiled_emit_flattened(store_id, model_id,
      target, p.type_name, p.relation_name)
    WHERE p.strategy IN ('flattened', 'conditioned')
    UNION ALL
    SELECT * FROM fga._compiled_emit_setop(store_id, model_id,
      target, p.type_name, p.relation_name)
    WHERE p.strategy = 'setop'
    UNION ALL
    SELECT * FROM fga._compiled_emit_recursive(store_id, model_id,
      target, p.type_name, p.relation_name)
    WHERE p.strategy = 'recursive'
    UNION ALL
    SELECT * FROM fga._compiled_emit_delegated(store_id, model_id,
      p.type_name, p.relation_name)
    WHERE p.strategy = 'delegated'
  ) AS b
  CROSS JOIN (VALUES ('objects'), ('subjects'), ('check')) AS k(kind)
  CROSS JOIN LATERAL (SELECT fga._compiled_name(
    p.type_name, p.relation_name, k.kind) AS name) AS n;
$$;

-- Serialises the generator's work on one store, for the rest of
-- the transaction. The two-int advisory lock form, with a class id
-- hashed from a constant naming this purpose, so the key cannot meet
-- an application's single-bigint advisory locks (another lock space)
-- and is unlikely to meet its two-int ones; the second int hashes the
-- store. Two stores whose hashes collide only wait for each other.
CREATE OR REPLACE FUNCTION fga._compiled_lock(store_id uuid)
RETURNS void
LANGUAGE sql
VOLATILE
SET search_path = fga, pg_temp
AS $$
  SELECT pg_advisory_xact_lock(
    hashtext('fga4postgres compiled relations'),
    hashtext(store_id::text));
$$;

-- Drops every registered function of a store and its registry
-- rows. Only registered functions: anything else in the schema
-- belongs to the application. A registered function that is
-- already gone (the application dropped its schema first) is
-- skipped: the registry still holds its oid, which no longer names
-- anything to drop.
CREATE OR REPLACE FUNCTION fga._compiled_drop(store_id uuid)
RETURNS void
LANGUAGE plpgsql
VOLATILE
SET search_path = fga, pg_temp
AS $$
DECLARE
  fn regprocedure;
BEGIN
  PERFORM fga._compiled_lock(store_id);
  FOR fn IN
    SELECT DISTINCT v.f
    FROM fga.compiled_relation r,
         LATERAL (VALUES (r.objects_fn), (r.subjects_fn),
                         (r.check_fn)) AS v(f)
    WHERE r.store = store_id
      AND EXISTS (SELECT FROM pg_proc p WHERE p.oid = v.f)
  LOOP
    EXECUTE format('DROP FUNCTION %s', fn);
  END LOOP;
  DELETE FROM fga.compiled_relation WHERE store = store_id;
  DELETE FROM fga.compiled_contextual WHERE store = store_id;
END;
$$;

-- Regenerates every function of an opted-in store from its latest
-- model, in the caller's transaction. A no-op for stores that did
-- not opt in.
--
-- Functions that survive a model change are replaced in place:
-- CREATE OR REPLACE keeps their oid, so an application's views and
-- anything else holding a function by oid stay valid (dropping one
-- would fail the model write with "other objects depend on it").
-- Cached plans are re-planned either way — a prepared statement
-- resolves the name again (TestCompiledPlanInvalidation). Only
-- registered functions the new model no longer has are dropped. A
-- same-signature function the engine did not register belongs to
-- the application: it refuses the model write instead of being
-- overwritten.
--
-- Two model writes to one store regenerate the same functions, so
-- they are serialised on the store's lock (_compiled_lock): the
-- second waits for the first to commit, then reads the registry it
-- left. Unserialised, the second regenerated from a registry that
-- did not show the first's rows, and left them (and their
-- functions) behind.
CREATE OR REPLACE FUNCTION fga._compiled_generate(store_id uuid)
RETURNS void
LANGUAGE plpgsql
VOLATILE
SET search_path = fga, pg_temp
AS $$
DECLARE
  target text;
  mid uuid;
  fns jsonb;
  fn record;
  clash text;
BEGIN
  SELECT cs.target_schema INTO target
  FROM fga.compiled_store cs WHERE cs.store = store_id;
  IF NOT FOUND THEN
    RETURN;
  END IF;
  -- Every statement below reads what a write that held the lock
  -- before us committed (a VOLATILE function's statements each take
  -- a new snapshot).
  PERFORM fga._compiled_lock(store_id);

  SELECT m.id INTO mid FROM fga.model m
  WHERE m.store = store_id ORDER BY m.id DESC LIMIT 1;

  SELECT coalesce(jsonb_agg(to_jsonb(f) ORDER BY f.ord, f.name),
                  '[]')
  INTO fns
  FROM fga._compiled_functions(store_id, mid, target) AS f
  WHERE mid IS NOT NULL;

  SELECT f ->> 'name' INTO clash
  FROM jsonb_array_elements(fns) AS f
  GROUP BY f ->> 'name' HAVING count(*) > 1 LIMIT 1;
  IF clash IS NOT NULL THEN
    RAISE EXCEPTION 'compiled relations: two relations would share '
      'the function name %', clash USING ERRCODE = 'YF156';
  END IF;

  -- Drop what was registered and is no longer generated.
  FOR fn IN
    SELECT DISTINCT v.f
    FROM fga.compiled_relation r,
         LATERAL (VALUES (r.objects_fn), (r.subjects_fn),
                         (r.check_fn)) AS v(f)
    WHERE r.store = store_id
      AND EXISTS (SELECT FROM pg_proc p WHERE p.oid = v.f)
      AND NOT EXISTS (
        SELECT FROM jsonb_array_elements(fns) AS g
        WHERE to_regprocedure(g ->> 'sig') = v.f)
  LOOP
    EXECUTE format('DROP FUNCTION %s', fn.f);
  END LOOP;

  SELECT g ->> 'sig' INTO clash
  FROM jsonb_array_elements(fns) AS g
  WHERE to_regprocedure(g ->> 'sig') IS NOT NULL
    AND NOT EXISTS (
      SELECT FROM fga.compiled_relation r
      WHERE r.store = store_id
        AND to_regprocedure(g ->> 'sig')
              IN (r.objects_fn, r.subjects_fn, r.check_fn))
  LIMIT 1;
  IF clash IS NOT NULL THEN
    RAISE EXCEPTION 'compiled relations: function % exists and was '
      'not generated by fga4postgres', clash
      USING ERRCODE = 'YF156';
  END IF;

  DELETE FROM fga.compiled_relation WHERE store = store_id;
  DELETE FROM fga.compiled_contextual WHERE store = store_id;

  FOR fn IN
    SELECT * FROM jsonb_to_recordset(fns) AS x(
      type_name text, relation_name text, kind text, name text,
      sig text, ddl text, strategy text, reason text)
  LOOP
    EXECUTE fn.ddl;
    EXECUTE format('COMMENT ON FUNCTION %s IS %L', fn.sig,
      fga._compiled_comment(store_id, mid, fn.type_name,
        fn.relation_name, fn.kind, fn.strategy, fn.reason));
  END LOOP;

  INSERT INTO fga.compiled_relation
  SELECT store_id, mid, x.type_name, x.relation_name,
    max(x.sig) FILTER (WHERE x.kind = 'objects')::regprocedure,
    max(x.sig) FILTER (WHERE x.kind = 'subjects')::regprocedure,
    max(x.sig) FILTER (WHERE x.kind = 'check')::regprocedure,
    min(x.strategy), min(x.reason)
  FROM jsonb_to_recordset(fns) AS x(
    type_name text, relation_name text, kind text, sig text,
    strategy text, reason text)
  GROUP BY x.type_name, x.relation_name;

  INSERT INTO fga.compiled_contextual
  SELECT store_id, mid, r.type_name, r.relation_name, s.kind, s.stmt
  FROM fga.compiled_relation r
  CROSS JOIN LATERAL fga._compiled_ctx_stmts(store_id, mid, target,
    r.type_name, r.relation_name) AS s
  WHERE r.store = store_id
    AND r.strategy IN ('flattened', 'conditioned');
END;
$$;

-- Opts a store in (or changes its subject sources) and generates
-- its functions for the latest model right away. The schema must
-- already exist: the application creates and owns it, so the
-- engine needs no database-level CREATE and a mistyped name is an
-- error rather than a new empty schema.
CREATE OR REPLACE FUNCTION fga.enable_compiled_relations(
  store uuid,
  target_schema text,
  subject_sources jsonb DEFAULT NULL
)
RETURNS void
LANGUAGE plpgsql
VOLATILE
SET search_path = fga, pg_temp
AS $$
DECLARE
  src record;
  m text[];
BEGIN
  IF NOT EXISTS (
    SELECT FROM fga.store s
    WHERE s.id = enable_compiled_relations.store
  ) THEN
    RAISE EXCEPTION 'store % not found', enable_compiled_relations.store
      USING ERRCODE = 'YF502';
  END IF;
  IF target_schema IN ('fga', 'cel', 'information_schema')
     OR target_schema LIKE 'pg\_%' THEN
    RAISE EXCEPTION 'schema ''%'' is reserved: compiled relations '
      'need a schema of their own', target_schema
      USING ERRCODE = 'YF100';
  END IF;
  IF NOT EXISTS (
    SELECT FROM pg_namespace n WHERE n.nspname = target_schema
  ) THEN
    RAISE EXCEPTION 'schema ''%'' does not exist: create it before '
      'enabling compiled relations', target_schema
      USING ERRCODE = 'YF100';
  END IF;
  IF EXISTS (
    SELECT FROM fga.compiled_store cs
    WHERE cs.target_schema = enable_compiled_relations.target_schema
      AND cs.store <> enable_compiled_relations.store
  ) THEN
    RAISE EXCEPTION 'schema ''%'' already holds another store''s '
      'compiled relations', target_schema USING ERRCODE = 'YF100';
  END IF;

  IF subject_sources IS NOT NULL THEN
    IF jsonb_typeof(subject_sources) <> 'object' THEN
      RAISE EXCEPTION 'subject_sources must be a json object'
        USING ERRCODE = 'YF100';
    END IF;
    FOR src IN SELECT * FROM jsonb_each(subject_sources) LOOP
      m := fga._compiled_parse_source(src.value #>> '{}');
      IF jsonb_typeof(src.value) <> 'string' OR m IS NULL
         OR NOT EXISTS (
           SELECT FROM pg_attribute a
           WHERE a.attrelid = to_regclass(
                   format('%I.%I', m[1], m[2]))
             AND a.attname = m[3] AND NOT a.attisdropped
             AND a.atttypid = 'uuid'::regtype
         )
      THEN
        RAISE EXCEPTION 'subject source for type ''%'' must name '
          'an existing uuid column as schema.table(column), got %',
          src.key, src.value USING ERRCODE = 'YF100';
      END IF;
    END LOOP;
  END IF;

  -- A different schema means the old functions go first.
  IF EXISTS (
    SELECT FROM fga.compiled_store cs
    WHERE cs.store = enable_compiled_relations.store
      AND cs.target_schema <> enable_compiled_relations.target_schema
  ) THEN
    PERFORM fga._compiled_drop(enable_compiled_relations.store);
  END IF;

  INSERT INTO fga.compiled_store AS cs
  VALUES (enable_compiled_relations.store, target_schema,
          subject_sources)
  ON CONFLICT ON CONSTRAINT compiled_store_pkey DO UPDATE
  SET target_schema = excluded.target_schema,
      subject_sources = excluded.subject_sources;

  PERFORM fga._compiled_generate(enable_compiled_relations.store);
END;
$$;

-- Opts a store out: drops exactly its registered functions.
CREATE OR REPLACE FUNCTION fga.disable_compiled_relations(
  store uuid
)
RETURNS void
LANGUAGE plpgsql
VOLATILE
SET search_path = fga, pg_temp
AS $$
BEGIN
  PERFORM fga._compiled_drop(disable_compiled_relations.store);
  DELETE FROM fga.compiled_store cs
  WHERE cs.store = disable_compiled_relations.store;
END;
$$;
